// --- HELPERS ---

const getTodayString = () => {
   const d = new Date();
   const year = d.getFullYear();
   const month = String(d.getMonth() + 1).padStart(2, '0');
   const day = String(d.getDate()).padStart(2, '0');
   return `${year}-${month}-${day}`;
};

const formatDisplayDate = (dateStr: string) => {
   try {
      const d = new Date(dateStr);
      return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
   } catch (e) {
      return dateStr;
   }
};

const getSafeErrorMessage = (err: any): string => {
   if (!err) return "Unknown error";
   if (typeof err === 'string') return err;
   if (err instanceof Error) return err.message;
   try {
      const json = JSON.stringify(err);
      if (json && json !== '{}' && !json.includes('[object Object]')) return json;
   } catch { }
   return String(err) === '[object Object]' ? 'Unknown Error (Object)' : String(err);
};

const copyToClipboard = async (text: string): Promise<boolean> => {
   // Try modern Clipboard API
   if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
      try {
         await navigator.clipboard.writeText(text);
         return true;
      } catch (err) {
         console.warn("Clipboard API failed, falling back...", err);
      }
   }

   // Fallback to legacy execCommand('copy')
   try {
      const textArea = document.createElement("textarea");
      textArea.value = text;
      // Ensure it's not visible but still part of the DOM
      textArea.style.position = "fixed";
      textArea.style.left = "-9999px";
      textArea.style.top = "0";
      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select();
      const successful = document.execCommand('copy');
      document.body.removeChild(textArea);
      return !!successful;
   } catch (err) {
      console.error("Fallback copy failed:", err);
      return false;
   }
};

