interface SidebarItemProps {
   view: AdminView;
   icon: any;
   label: string;
   requiredPerm: string;
   activeView: AdminView;
   hasPermission: (perm: string) => boolean;
   onSelect: (view: AdminView) => void;
   hiddenMenus?: string[];
}

const SidebarItem = React.memo(({ view, icon: Icon, label, requiredPerm, activeView, hasPermission, onSelect, hiddenMenus }: SidebarItemProps) => {
   if (requiredPerm && !hasPermission(requiredPerm)) return null;
   if (hiddenMenus?.includes(view)) return null;

   // Auto-scroll to active item
   const ref = useRef<HTMLAnchorElement>(null);
   useEffect(() => {
      if (activeView === view && ref.current) {
         ref.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
   }, [activeView, view]);

   return (
      <a
         ref={ref}
         href={`?view=${view}`}
         onClick={(e) => {
// Client-side state transition on normal left click without modifiers
            if (!e.metaKey && !e.ctrlKey && !e.shiftKey && e.button === 0) {
               e.preventDefault();
               onSelect(view);
            }
         }}
         className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 ${activeView === view ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' : 'text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'}`}
      >
         <Icon size={20} /> <span className="font-medium text-sm">{label}</span>
      </a>
   );
});
