   const handleCopyImportedData = () => {
      if (importedData.length === 0) return;
      if (!importedColumns.includes('Konversi ID Pesanan')) return;
      
      const targetColumns = ['Konversi ID Pesanan', 'Keterangan', '', 'MSKU', 'QTY'];
      const rows = importedData.map(row => {
         return targetColumns.map(col => {
            if (col === '') return '';
            return row[col] || '';
         }).join('\t');
      });
      const tsv = rows.join('\n');
      navigator.clipboard.writeText(tsv).then(() => {
         alert('Berhasil menyalin semua data import ke clipboard!');
      }).catch(() => {
         alert('Gagal menyalin data.');
      });
   };

   const handleProcessPastedBarcodes = () => {
      if (!pastedBarcodes.trim()) return;
      const lines = pastedBarcodes.split('\n').filter(l => l.trim() !== '');
      const data = lines.map(l => {
         const parts = l.split(/,|\t/).map(p => p.trim()).filter(p => p !== '');
         return {
            'Barcode Data': parts[0] || '',
            'Keterangan': parts[1] || '',
            'MSKU': parts[2] || '',
            'QTY': parts[3] || ''
         };
      });
      setParsedPastedData(data);
      if (Object.keys(excelMapping).length === 0) {
         setImportedColumns(['Barcode Data', 'Keterangan', 'MSKU', 'QTY']);
         setImportedData(data);
      }
   };

   const handleExcelUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (evt) => {
         const bstr = evt.target?.result;
         const wb = XLSX.read(bstr, { type: 'binary' });
         const wsname = wb.SheetNames[0];
         const ws = wb.Sheets[wsname];
         const data = XLSX.utils.sheet_to_json(ws, { header: 1 }) as any[][];
         
         if (data.length > 0) {
            const headers = data[0] as string[];
            let awbIdx = -1;
            let idPesananIdx = -1;
            headers.forEach((h, idx) => {
                if (!h) return;
                const upper = h.toString().trim().toUpperCase();
                if (upper === 'AWB/NO. TRACKING' || upper === 'NO. TRACKING' || upper === 'AWB') awbIdx = idx;
                if (upper === 'ID PESANAN' || upper === 'ORDER ID') idPesananIdx = idx;
            });
            
            if (awbIdx !== -1 && idPesananIdx !== -1) {
                const mapping: Record<string, string> = {};
                for (let i = 1; i < data.length; i++) {
                    const row = data[i];
                    if (row && row[awbIdx]) {
                        const awb = String(row[awbIdx]).trim();
                        const idPesanan = String(row[idPesananIdx] || '').trim();
                        mapping[awb] = idPesanan;
                    }
                }
                setExcelMapping(mapping);
                alert(`Berhasil memuat ${Object.keys(mapping).length} data pemetaan dari Excel.`);
            } else {
                alert("Kolom 'AWB/No. Tracking' atau 'ID Pesanan' tidak ditemukan di file Excel. Pastikan nama kolom sesuai.");
            }
         }
      };
      reader.readAsBinaryString(file);
   };

