   // Dual-Sync (Supabase + Firestore) listener & fast hydration for Admin Shift Notes
   useEffect(() => {
      let unsubscribe: (() => void) | null = null;

      // 1. Fast Instant Hydration from Supabase
      const fetchNotesFromSupabase = async () => {
         try {
            const { data, error } = await supabase
               .from('admin_shift_notes')
               .select('*')
               .order('created_at', { ascending: false });

            if (!error && data && data.length > 0) {
               setAdminNotes(data as AdminShiftNote[]);
            }
         } catch (err) {
            // Silently ignore if table does not exist in Supabase yet
         }
      };

      fetchNotesFromSupabase();

      // 2. Real-time Firestore Stream for Live Updates Across All Admins
      const initNotesListener = async () => {
         try {
            const { db } = await import('../services/firebaseClient');
            const { collection, onSnapshot, query, orderBy } = await import('firebase/firestore');

            const q = query(collection(db, 'admin_shift_notes'), orderBy('created_at', 'desc'));
            unsubscribe = onSnapshot(q, (snapshot) => {
               const notes: AdminShiftNote[] = [];
               snapshot.forEach((docSnap) => {
                  notes.push({ id: docSnap.id, ...docSnap.data() } as AdminShiftNote);
               });
               if (notes.length > 0) {
                  setAdminNotes(notes);
               }
            }, (err) => {
               console.error('Error listening to admin_shift_notes in Firestore:', err);
            });
         } catch (err) {
            console.error('Failed to init notes listener:', err);
         }
      };

      initNotesListener();
      return () => {
         if (unsubscribe) unsubscribe();
      };
   }, []);

   const isUserSuperDev = (usernameOrEmail?: string | null, role?: string | null) => {
      const lower = (usernameOrEmail || '').toLowerCase();
      const roleLower = (role || '').toLowerCase();
      return lower.includes('superdev') || lower.includes('super_dev') || lower.includes('superadmin') || roleLower === 'super_admin' || roleLower === 'god_mode';
   };

