   const handleCreateAdminNote = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newNoteTitle.trim() || !newNoteContent.trim()) {
         alert("Judul dan Isi catatan tidak boleh kosong.");
         return;
      }
      setIsSavingNote(true);
      try {
         const noteData: Omit<AdminShiftNote, 'id'> = {
            title: newNoteTitle.trim(),
            content: newNoteContent.trim(),
            priority: newNotePriority,
            created_by: currentAdmin?.username || currentAdmin?.email || 'Admin',
            created_at: Date.now(),
            is_active: true,
            target_role: newNoteTargetRole,
            read_by: []
         };

         // Dual Write: 1. Firestore Real-Time
         const { db } = await import('../services/firebaseClient');
         const { collection, addDoc } = await import('firebase/firestore');
         const docRef = await addDoc(collection(db, 'admin_shift_notes'), noteData);

         // Dual Write: 2. Supabase Fast Backup
         try {
            await supabase.from('admin_shift_notes').insert([{ id: docRef.id, ...noteData }]);
         } catch (spErr) {
            console.warn("Supabase backup insert notice:", spErr);
         }

         setNewNoteTitle('');
         setNewNoteContent('');
         setNewNotePriority('SHIFT_HANDOVER');
         setIsCreateNoteModalOpen(false);
         setSuccessToast("Catatan Admin berhasil disiarkan ke Supabase + Firestore!");
      } catch (err: any) {
         console.error("Gagal membuat catatan admin:", err);
         alert("Gagal menyimpan catatan: " + err.message);
      } finally {
         setIsSavingNote(false);
      }
   };

   const handleAcknowledgeNote = async (noteId: string) => {
      try {
         const userIdentifier = currentAdmin?.email || currentAdmin?.username || 'Admin';
         const userName = currentAdmin?.username || currentAdmin?.email || 'Admin';

         const readEntry: AdminShiftNoteRead = {
            user_email: userIdentifier,
            user_name: userName,
            read_at: Date.now()
         };

         // Update Local State Immediately for Instant UI Feedback
         setAdminNotes(prev => prev.map(n => {
            if (n.id === noteId) {
               return { ...n, read_by: [...(n.read_by || []), readEntry] };
            }
            return n;
         }));
         setDismissedNoteIds(prev => [...prev, noteId]);

         // Dual Update: Firestore
         const { db } = await import('../services/firebaseClient');
         const { doc, updateDoc, arrayUnion } = await import('firebase/firestore');
         const noteRef = doc(db, 'admin_shift_notes', noteId);
         await updateDoc(noteRef, {
            read_by: arrayUnion(readEntry)
         });

         // Dual Update: Supabase
         try {
            const currentNote = adminNotes.find(n => n.id === noteId);
            if (currentNote) {
               const updatedReaders = [...(currentNote.read_by || []), readEntry];
               await supabase.from('admin_shift_notes').update({ read_by: updatedReaders }).eq('id', noteId);
            }
         } catch (spErr) {
            console.warn("Supabase reader update notice:", spErr);
         }
      } catch (err: any) {
         console.error("Gagal mengonfirmasi pembacaan note:", err);
      }
   };

   const handleToggleNoteActive = async (noteId: string, currentActiveState: boolean) => {
      try {
         const nextState = !currentActiveState;
         setAdminNotes(prev => prev.map(n => n.id === noteId ? { ...n, is_active: nextState } : n));

         // Dual Update: Firestore
         const { db } = await import('../services/firebaseClient');
         const { doc, updateDoc } = await import('firebase/firestore');
         const noteRef = doc(db, 'admin_shift_notes', noteId);
         await updateDoc(noteRef, { is_active: nextState });

         // Dual Update: Supabase
         try {
            await supabase.from('admin_shift_notes').update({ is_active: nextState }).eq('id', noteId);
         } catch (spErr) {
            console.warn("Supabase toggle notice:", spErr);
         }
      } catch (err: any) {
         console.error("Gagal mengubah status catatan:", err);
      }
   };

   const handleDeleteAdminNote = async (noteId: string) => {
      const targetNote = adminNotes.find(n => n.id === noteId);
      if (!targetNote) return;

      const isNoteCreatedBySuperDev = isUserSuperDev(targetNote.created_by);
      const isCurrentUserSuperDev = isUserSuperDev(currentAdmin?.username || currentAdmin?.email, currentAdmin?.role);

      if (isNoteCreatedBySuperDev && !isCurrentUserSuperDev) {
         alert("⛔ AKSES DITOLAK: Catatan yang dibuat oleh SuperDev tidak dapat dihapus oleh akun admin lain.");
         return;
      }

      if (!window.confirm("Apakah Anda yakin ingin menghapus catatan ini secara permanen?")) return;
      try {
         setAdminNotes(prev => prev.filter(n => n.id !== noteId));

         // Dual Delete: Firestore
         const { db } = await import('../services/firebaseClient');
         const { doc, deleteDoc } = await import('firebase/firestore');
         await deleteDoc(doc(db, 'admin_shift_notes', noteId));

         // Dual Delete: Supabase
         try {
            await supabase.from('admin_shift_notes').delete().eq('id', noteId);
         } catch (spErr) {
            console.warn("Supabase delete notice:", spErr);
         }
      } catch (err: any) {
         console.error("Gagal menghapus catatan:", err);
      }
   };
   
     const handleGlobalSearchFs = async () => {
        const term = globalSearchTermFs.trim();
        if (!term || term.length < 3) {
           alert("Masukkan minimal 3 karakter.");
           return;
        }
  
        setIsGlobalSearchingFs(true);
        const upper = term.toUpperCase();
        console.log(`[SYS] Deep Hunt Barcode (Firestore): ${upper}`);
  
         try {
            const { db } = await import('../services/firebaseClient');
            const { collection, getDocs, query, where, orderBy } = await import('firebase/firestore');
            let allData: any[] = [];
   
            const variations = Array.from(new Set([term, upper, term.toLowerCase()]));
            
            // Query 1: Search in barcode
            const q1 = query(collection(db, 'scanned_items'), where('barcode', 'in', variations));
            const snap1 = await getDocs(q1);
            snap1.forEach(doc => {
              allData.push({ ...doc.data(), id: doc.id, source: 'FIRESTORE' });
            });

            // Query 2: Search in destination
            const q2 = query(collection(db, 'scanned_items'), where('destination', 'in', variations));
            const snap2 = await getDocs(q2);
            snap2.forEach(doc => {
              if (!allData.find(d => d.id === doc.id)) {
                 allData.push({ ...doc.data(), id: doc.id, source: 'FIRESTORE' });
              }
            });

            // Query 3: Search in description
            const q3 = query(collection(db, 'scanned_items'), where('description', 'in', variations));
            const snap3 = await getDocs(q3);
            snap3.forEach(doc => {
              if (!allData.find(d => d.id === doc.id)) {
                 allData.push({ ...doc.data(), id: doc.id, source: 'FIRESTORE' });
              }
            });
           
           // Sort by timestamp desc locally since we only queried barcode
           allData.sort((a, b) => b.timestamp - a.timestamp);
           
           setGlobalSearchResultsFs(allData);
        } catch (err: any) {
           console.error("Error global search firestore:", err);
           alert("Gagal mencari data di Firestore: " + err.message);
        } finally {
           setIsGlobalSearchingFs(false);
        }
     };

   const handleGlobalSearch = async () => {
      const term = globalSearchTerm.trim();
      if (!term || term.length < 3) {
         alert("Masukkan minimal 3 karakter.");
         return;
      }

      setIsGlobalSearching(true);
      const upper = term.toUpperCase();
      const lower = term.toLowerCase();
      const variations = Array.from(new Set([term, upper, lower]));

      try {
         const { supabase, supabaseNew, supabaseSpecialOld } = await import('../services/supabaseClient');
         const { db } = await import('../services/firebaseClient');
         const { collection, getDocs, query, where } = await import('firebase/firestore');

         const fetchSb = async (client: any, sourceDb: string, label: string) => {
            try {
               const isLikelyBarcode = term.length >= 8 && !term.includes(' ');
               const orQuery = isLikelyBarcode
                  ? `barcode.eq.${upper}`
                  : `barcode.eq.${upper},barcode.ilike.%${term}%,destination.ilike.%${term}%`;

               const { data, error } = await client
                  .from('scanned_items')
                  .select('*')
                  .or(orQuery)
                  .limit(100);
               if (error || !data) return [];
               return data.map((item: any) => ({ ...item, source_db: sourceDb, source_label: label }));
            } catch (e) {
               return [];
            }
         };

         const fetchFs = async () => {
            try {
               let fsItems: any[] = [];
               const q1 = query(collection(db, 'scanned_items'), where('barcode', 'in', variations));
               const snap1 = await getDocs(q1);
               snap1.forEach(doc => {
                  fsItems.push({ ...doc.data(), id: doc.id, source_db: 'FIRESTORE', source_label: 'Firestore' });
               });

               const q2 = query(collection(db, 'scanned_items'), where('destination', 'in', variations));
               const snap2 = await getDocs(q2);
               snap2.forEach(doc => {
                  if (!fsItems.find(d => d.id === doc.id)) {
                     fsItems.push({ ...doc.data(), id: doc.id, source_db: 'FIRESTORE', source_label: 'Firestore' });
                  }
               });
               return fsItems;
            } catch (e) {
               return [];
            }
         };

         const [primaryData, archiveData, oldData, fsData] = await Promise.all([
            fetchSb(supabase, 'SUPABASE_PRIMARY', 'Supabase Utama'),
            fetchSb(supabaseNew, 'SUPABASE_ARCHIVE', 'Supabase Archive'),
            fetchSb(supabaseSpecialOld, 'SUPABASE_OLD', 'Supabase Lama'),
            fetchFs()
         ]);

         let allMerged = [...primaryData, ...archiveData, ...oldData, ...fsData];

         const uniqueMap = new Map();
         allMerged.forEach(item => {
            const key = item.id || `${item.barcode}_${item.role}_${item.timestamp}`;
            if (!uniqueMap.has(key)) {
               uniqueMap.set(key, item);
            }
         });

         const sortedResults = Array.from(uniqueMap.values()).sort((a: any, b: any) => {
            const getT = (x: any) => x.timestamp ? new Date(x.timestamp).getTime() : 0;
            return getT(b) - getT(a);
         });

         setGlobalSearchResults(sortedResults);
         if (sortedResults.length === 0) {
            alert(`Tidak ditemukan data resi "${term}" di 4 Database (Supabase Utama, Archive, Supabase Lama, maupun Firestore).`);
         }
      } catch (err: any) {
         console.error("Critical Failure in Global Search:", err);
         alert("Terjadi kesalahan saat mencari data: " + err.message);
      } finally {
         setIsGlobalSearching(false);
      }
   };

