   const [syncEndDate, setSyncEndDate] = useState(() => new Date().toISOString().split('T')[0]);
   const [syncRole, setSyncRole] = useState('SEMUA');
   const [syncCollectionName, setSyncCollectionName] = useState('scanned_items');
   const [isSyncingFs, setIsSyncingFs] = useState(false);
   const [syncProgressFs, setSyncProgressFs] = useState(0);
   const [syncTotalCountFs, setSyncTotalCountFs] = useState(0);
   const [syncProcessedCountFs, setSyncProcessedCountFs] = useState(0);
   const [syncBatchCurrentFs, setSyncBatchCurrentFs] = useState(0);
   const [syncBatchTotalFs, setSyncBatchTotalFs] = useState(0);
   const [syncStatusMsgFs, setSyncStatusMsgFs] = useState('');
   const [isVerifyingFs, setIsVerifyingFs] = useState(false);
   const [showSyncAuditModal, setShowSyncAuditModal] = useState(false);
   const [syncRoleBreakdownFs, setSyncRoleBreakdownFs] = useState<Record<string, number>>({});
   const [syncAuditReport, setSyncAuditReport] = useState<{
      dateStr: string;
      sbTotal: number;
      fsTotal: number;
      sbRoles: Record<string, number>;
      fsRoles: Record<string, number>;
      matched: boolean;
   } | null>(null);

   const handleVerifyAndMatchData = async (startDate?: string, endDate?: string) => {
      const start = startDate || syncStartDate || getTodayString();
      const end = endDate || syncEndDate || start;
      setIsVerifyingFs(true);
      setSyncStatusMsgFs(`🔍 Memeriksa & Membandingkan Rincian Data Supabase vs Firestore (${start} s/d ${end})...`);
      try {
         const startMs = new Date(`${start}T00:00:00`).getTime();
         const endMs = new Date(`${end}T23:59:59.999`).getTime();

         // 1. Fetch Supabase count & role breakdown
         let allSbData: any[] = [];
         let page = 0;
         const pageSize = 1000;
         let hasMore = true;

         while (hasMore) {
            const { data, error } = await supabase
               .from('scanned_items')
               .select('role')
               .gte('timestamp', startMs)
               .lte('timestamp', endMs)
               .order('id', { ascending: true })
               .range(page * pageSize, (page + 1) * pageSize - 1);

            if (error) break;
            if (data && data.length > 0) {
               allSbData = allSbData.concat(data);
               if (data.length < pageSize) hasMore = false;
               else page++;
            } else {
               hasMore = false;
            }
         }

         const sbRoles: Record<string, number> = {};
         allSbData.forEach(row => {
            const r = (row.role || 'MISSING_ROLE').toUpperCase();
            sbRoles[r] = (sbRoles[r] || 0) + 1;
         });

         // 2. Fetch Firestore count & role breakdown
         const activeFsQuery = fsQuery(
            collection(db, syncCollectionName.trim() || 'scanned_items'),
            where('timestamp', '>=', startMs),
            where('timestamp', '<=', endMs)
         );
         const fsSnap = await getDocs(activeFsQuery);

         const fsRoles: Record<string, number> = {};
         fsSnap.docs.forEach(docSnap => {
            const d = docSnap.data();
            const r = (d.role || 'MISSING_ROLE').toUpperCase();
            fsRoles[r] = (fsRoles[r] || 0) + 1;
         });

         const report = {
            dateStr: start === end ? start : `${start} s/d ${end}`,
            sbTotal: allSbData.length,
            fsTotal: fsSnap.docs.length,
            sbRoles,
            fsRoles,
            matched: allSbData.length === fsSnap.docs.length
         };

         setSyncAuditReport(report);
         setShowSyncAuditModal(true);
         setSyncStatusMsgFs(`✅ Verifikasi Selesai: ${report.sbTotal} (Supabase) vs ${report.fsTotal} (Firestore)`);
         return report;
      } catch (err: any) {
         console.error("Verification error:", err);
         setSyncStatusMsgFs(`❌ Error Verifikasi: ${err.message || 'Gagal memeriksa'}`);
      } finally {
         setIsVerifyingFs(false);
      }
   };

   // Secret key listener for Search Data 2 DevMode (typing 'devmodenew')
   useEffect(() => {
      const sequence = ['d', 'e', 'v', 'm', 'o', 'd', 'e', 'n', 'e', 'w'];
      let currentIndex = 0;

      const handleKeyDown = (e: KeyboardEvent) => {
         if (activeView !== 'SEARCH_ALL_FIRESTORE') return;
         const target = e.target as HTMLElement;
         if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.tagName === 'SELECT')) {
            return;
         }

         if (e.key.toLowerCase() === sequence[currentIndex]) {
            currentIndex++;
            if (currentIndex === sequence.length) {
               setShowFsSyncDevMode(prev => {
                  const newState = !prev;
                  setSuccessToast(newState ? "⚡ Dev Mode Rahasia Activated!" : "Dev Mode Rahasia Deactivated");
                  return newState;
               });
               currentIndex = 0;
            }
         } else {
            currentIndex = 0;
         }
      };

      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
   }, [activeView]);

   const handleSyncSupabaseToFirestore = async () => {
      if (isSyncingFs) return;
      setIsSyncingFs(true);
      setSyncProgressFs(0);
      setSyncProcessedCountFs(0);
      setSyncTotalCountFs(0);
      setSyncBatchCurrentFs(0);
      setSyncBatchTotalFs(0);
      setSyncStatusMsgFs('Mengambil data dari Supabase...');

      try {
         const targetCollection = syncCollectionName.trim() || 'scanned_items';

         let allItems: any[] = [];
         let page = 0;
         const pageSize = 1000;
         let hasMore = true;

         while (hasMore) {
            let query = supabase
               .from('scanned_items')
               .select('*')
               .order('id', { ascending: true });

            if (syncStartDate) {
               const startTs = new Date(`${syncStartDate}T00:00:00`).getTime();
               if (!isNaN(startTs)) {
                  query = query.gte('timestamp', startTs);
               }
            }
            if (syncEndDate) {
               const endTs = new Date(`${syncEndDate}T23:59:59.999`).getTime();
               if (!isNaN(endTs)) {
                  query = query.lte('timestamp', endTs);
               }
            }
            if (syncRole && syncRole !== 'SEMUA') {
               query = query.eq('role', syncRole);
            }

            const { data, error } = await query.range(page * pageSize, (page + 1) * pageSize - 1);
            if (error) {
               throw new Error(`Gagal mengambil data dari Supabase: ${error.message}`);
            }

            if (data && data.length > 0) {
               allItems = allItems.concat(data);
               if (data.length < pageSize) {
                  hasMore = false;
               } else {
                  page++;
               }
            } else {
               hasMore = false;
            }
         }

         if (allItems.length === 0) {
            setSyncStatusMsgFs('⚠️ Tidak ada data Supabase yang ditemukan untuk filter ini.');
            setIsSyncingFs(false);
            return;
         }

         const totalCount = allItems.length;
         const roleBreakdown: Record<string, number> = {};
         allItems.forEach((item: any) => {
            const r = (item.role || 'UNKNOWN').toUpperCase();
            roleBreakdown[r] = (roleBreakdown[r] || 0) + 1;
         });
         setSyncRoleBreakdownFs(roleBreakdown);

         const BATCH_SIZE = 350;
         const totalBatches = Math.ceil(totalCount / BATCH_SIZE);

         setSyncTotalCountFs(totalCount);
         setSyncBatchTotalFs(totalBatches);
         setSyncStatusMsgFs(`Ditemukan ${totalCount} data. Memulai sinkronisasi dalam ${totalBatches} batch...`);

         let processed = 0;
         for (let b = 0; b < totalBatches; b++) {
            const batchItems = allItems.slice(b * BATCH_SIZE, (b + 1) * BATCH_SIZE);
            const batch = writeBatch(db);

            for (const item of batchItems) {
               const docId = item.id ? String(item.id) : `${item.barcode || 'item'}_${item.role || ''}_${Date.now()}`;
               const docRef = doc(db, targetCollection, docId);

               const cleanItem: Record<string, any> = {};
               Object.keys(item).forEach((key) => {
                  if (item[key] !== undefined) {
                     cleanItem[key] = item[key];
                  }
               });

               batch.set(docRef, cleanItem, { merge: true });
            }

            await batch.commit();
            processed += batchItems.length;

            const batchNum = b + 1;
            const progressPct = Math.round((processed / totalCount) * 100);

            setSyncProcessedCountFs(processed);
            setSyncBatchCurrentFs(batchNum);
            setSyncProgressFs(progressPct);
            setSyncStatusMsgFs(`Selesai Batch ${batchNum} dari ${totalBatches} (${processed} / ${totalCount} data disinkronkan)`);

            await new Promise((resolve) => setTimeout(resolve, 50));
         }

         setSyncStatusMsgFs(`✅ Sinkronisasi Berhasil! Total ${totalCount} data dikirim ke collection '${targetCollection}'.`);
         setSuccessToast(`Sinkronisasi Supabase ➔ Firestore selesai (${totalCount} data)!`);
      } catch (err: any) {
         console.error('Error syncing Supabase to Firestore:', err);
         setSyncStatusMsgFs(`❌ Gagal Sinkronisasi: ${err.message || 'Error tidak diketahui'}`);
      } finally {
         setIsSyncingFs(false);
      }
   };
   // 13. Failed Scans State
      const handleSyncSupabaseToFirestoreByDayRange = async () => {
      if (isSyncingFs) return;
      if (!syncStartDate || !syncEndDate) {
         alert('Silakan pilih Tanggal Mulai dan Tanggal Akhir!');
         return;
      }

      const startDateObj = new Date(`${syncStartDate}T00:00:00`);
      const endDateObj = new Date(`${syncEndDate}T00:00:00`);

      if (isNaN(startDateObj.getTime()) || isNaN(endDateObj.getTime())) {
         alert('Format tanggal tidak valid!');
         return;
      }

      if (startDateObj > endDateObj) {
         alert('Tanggal Mulai tidak boleh lebih besar dari Tanggal Akhir!');
         return;
      }

      setIsSyncingFs(true);
      setSyncProgressFs(0);
      setSyncProcessedCountFs(0);
      setSyncTotalCountFs(0);
      setSyncBatchCurrentFs(0);
      setSyncBatchTotalFs(0);

      const targetCollection = syncCollectionName.trim() || 'scanned_items';

      // Build array of dates to process
      const datesToProcess: { year: number; month: string; day: string; dateStr: string; displayStr: string }[] = [];
      let curr = new Date(startDateObj);
      while (curr <= endDateObj) {
         const y = curr.getFullYear();
         const m = String(curr.getMonth() + 1).padStart(2, '0');
         const d = String(curr.getDate()).padStart(2, '0');
         datesToProcess.push({
            year: y,
            month: m,
            day: d,
            dateStr: `${y}-${m}-${d}`,
            displayStr: `${d}/${m}/${y}`
         });
         curr.setDate(curr.getDate() + 1);
      }

      setSyncStatusMsgFs(`🚀 Memulai Sinkronisasi Rentang (${datesToProcess.length} hari: ${datesToProcess[0].displayStr} s/d ${datesToProcess[datesToProcess.length - 1].displayStr})...`);

      let grandTotalProcessed = 0;

      for (let i = 0; i < datesToProcess.length; i++) {
         const dateInfo = datesToProcess[i];
         let daySuccess = false;
         let retryAttempt = 0;

         while (!daySuccess) {
            try {
               retryAttempt++;
               const statusPrefix = retryAttempt > 1 ? `[Retry #${retryAttempt}] ` : '';
               setSyncStatusMsgFs(`${statusPrefix}Mengambil data Supabase tanggal ${dateInfo.displayStr} (${i + 1}/${datesToProcess.length} hari)...`);

               const startTs = new Date(`${dateInfo.dateStr}T00:00:00`).getTime();
               const endTs = new Date(`${dateInfo.dateStr}T23:59:59.999`).getTime();

               let allItems: any[] = [];
               let page = 0;
               const pageSize = 1000;
               let hasMore = true;

               while (hasMore) {
                  let query = supabase
                     .from('scanned_items')
                     .select('*')
                     .gte('timestamp', startTs)
                     .lte('timestamp', endTs)
                     .order('id', { ascending: true })
                     .range(page * pageSize, (page + 1) * pageSize - 1);

                  if (syncRole && syncRole !== 'SEMUA') {
                     query = query.eq('role', syncRole);
                  }

                  const { data, error } = await query;
                  if (error) {
                     throw new Error(`Gagal mengambil data dari Supabase: ${error.message}`);
                  }

                  if (data && data.length > 0) {
                     allItems = allItems.concat(data);
                     if (data.length < pageSize) {
                        hasMore = false;
                     } else {
                        page++;
                     }
                  } else {
                     hasMore = false;
                  }
               }

               if (allItems.length === 0) {
                  setSyncStatusMsgFs(`ℹ️ Tanggal ${dateInfo.displayStr}: Tidak ada data Supabase ditemukan. Lanjut...`);
                  daySuccess = true;
                  await new Promise(resolve => setTimeout(resolve, 300));
                  break;
               }

               const totalCount = allItems.length;
               const roleBreakdown: Record<string, number> = {};
               allItems.forEach((item: any) => {
                  const r = (item.role || 'UNKNOWN').toUpperCase();
                  roleBreakdown[r] = (roleBreakdown[r] || 0) + 1;
               });
               setSyncRoleBreakdownFs(roleBreakdown);

               const BATCH_SIZE = 350;
               const totalBatches = Math.ceil(totalCount / BATCH_SIZE);

               setSyncTotalCountFs(totalCount);
               setSyncBatchTotalFs(totalBatches);
               setSyncStatusMsgFs(`Tanggal ${dateInfo.displayStr}: Ditemukan ${totalCount} data. Memproses ${totalBatches} batch...`);

               let processed = 0;
               for (let b = 0; b < totalBatches; b++) {
                  const batchItems = allItems.slice(b * BATCH_SIZE, (b + 1) * BATCH_SIZE);
                  const batch = writeBatch(db);

                  for (const item of batchItems) {
                     const docId = item.id ? String(item.id) : `${item.barcode || 'item'}_${item.role || ''}_${Date.now()}`;
                     const docRef = doc(db, targetCollection, docId);

                     const cleanItem: Record<string, any> = {};
                     Object.keys(item).forEach((key) => {
                        if (item[key] !== undefined) {
                           cleanItem[key] = item[key];
                        }
                     });

                     batch.set(docRef, cleanItem, { merge: true });
                  }

                  await batch.commit();
                  processed += batchItems.length;

                  const batchNum = b + 1;
                  const progressPct = Math.round((processed / totalCount) * 100);

                  setSyncProcessedCountFs(processed);
                  setSyncBatchCurrentFs(batchNum);
                  setSyncProgressFs(progressPct);
                  setSyncStatusMsgFs(`[${dateInfo.displayStr}] Batch ${batchNum}/${totalBatches} selesai (${processed}/${totalCount} data)`);

                  await new Promise((resolve) => setTimeout(resolve, 50));
               }

               grandTotalProcessed += processed;
               daySuccess = true;
               setSyncStatusMsgFs(`✅ Tanggal ${dateInfo.displayStr} Berhasil! (${processed} data). Lanjut ke tanggal berikutnya...`);
               await new Promise(resolve => setTimeout(resolve, 800));
            } catch (err: any) {
               console.error(`Error sync date ${dateInfo.displayStr}:`, err);
               const errMsg = err?.message || 'timeout/network error';
               setSyncStatusMsgFs(`⚠️ Gagal Tanggal ${dateInfo.displayStr}: ${errMsg}. Mengulang otomatis dalam 3 detik...`);
               await new Promise(resolve => setTimeout(resolve, 3000));
            }
         }
      }

      setSyncStatusMsgFs(`✅ Sinkronisasi Berhasil! Total ${grandTotalProcessed} data dikirim ke collection '${targetCollection}'.`);
      setSuccessToast(`Sinkronisasi Rentang Selesai! Total ${grandTotalProcessed} data dikirim ke Firestore.`);
      setIsSyncingFs(false);
   };

   const [selectedFailedScanIds, setSelectedFailedScanIds] = useState<string[]>([]);
   const [isResending, setIsResending] = useState(false);

   // 14. Invoice Check State
   const [kalindoDataInput, setKalindoDataInput] = useState('');
   const [gineeDataInput, setGineeDataInput] = useState('');
   const [isComparingInvoice, setIsComparingInvoice] = useState(false);
