   const [isSavingSettings, setIsSavingSettings] = useState(false);

   useEffect(() => {
      // Fetch initial settings from Supabase database (Universal for ALL users)
      const fetchSettings = async () => {
         try {
            const { data, error } = await supabase.from('app_settings').select('*').eq('id', 1).single();
            if (!error && data) {
               if (data.skip_duplicate_batch !== undefined) setSkipDuplicateBatch(!!data.skip_duplicate_batch);
               if (data.skip_duplicate_checker !== undefined) setSkipDuplicateChecker(!!data.skip_duplicate_checker);
               if (data.strict_resi_mode !== undefined) setStrictResiMode(!!data.strict_resi_mode);
               if (data.hide_expired_resi !== undefined && data.hide_expired_resi !== null) {
                  setHideExpiredResi(!!data.hide_expired_resi);
               }
            }

            const { data: menuData } = await supabase.from('app_settings').select('setting_value').eq('setting_key', 'hidden_menus').maybeSingle();
            if (menuData && menuData.setting_value) {
               try {
                  const parsed = JSON.parse(menuData.setting_value);
                  if (Array.isArray(parsed)) {
                     setHiddenMenus(parsed);
                     localStorage.setItem('hidden_admin_menus', JSON.stringify(parsed));
                  }
               } catch (e) {
                  console.error("Failed to parse hidden_menus from DB", e);
               }
            }
         } catch (err) {
            console.error("Error fetching settings:", err);
         }
      };
      fetchSettings();

      // Realtime listener for universal settings changes across all users & devices
      const channel = supabase
         .channel('app_settings_admin_changes')
         .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'app_settings' }, (payload) => {
            if (payload.new) {
               const data = payload.new;
               if (data.skip_duplicate_batch !== undefined) setSkipDuplicateBatch(!!data.skip_duplicate_batch);
               if (data.skip_duplicate_checker !== undefined) setSkipDuplicateChecker(!!data.skip_duplicate_checker);
               if (data.strict_resi_mode !== undefined) setStrictResiMode(!!data.strict_resi_mode);
               if (data.hide_expired_resi !== undefined && data.hide_expired_resi !== null) {
                  setHideExpiredResi(!!data.hide_expired_resi);
               }
               
               if (data.setting_key === 'hidden_menus' && data.setting_value) {
                  try {
                     const parsed = JSON.parse(data.setting_value);
                     if (Array.isArray(parsed)) {
                        setHiddenMenus(parsed);
                        localStorage.setItem('hidden_admin_menus', JSON.stringify(parsed));
                     }
                  } catch(e) {}
               }
            }
         })
         .subscribe();

      return () => {
         supabase.removeChannel(channel);
      };
   }, []);

