    const handleEditBarcodeInCompareCol = async (col: 'BATCH' | 'PICKER' | 'CHECKER' | 'PACKING', oldBarcode: string) => {
       const newBarcode = window.prompt(`Ubah barcode "${oldBarcode}" pada sumber "${col}" menjadi:`, oldBarcode);
       if (!newBarcode) return;
       const newBarcodeClean = newBarcode.trim();
       if (!newBarcodeClean || newBarcodeClean === oldBarcode) return;

       try {
          if (col === 'BATCH') {
             const { error } = await supabase
                .from('batch_items')
                .update({ barcode: newBarcodeClean })
                .eq('barcode', oldBarcode);
             if (error) throw error;
          } else {
             const rolesToUpdate = col === 'PICKER' ? ['PICKER', 'PICKER_2', 'OJOL'] : [col];
             const { error } = await supabase
                .from('scanned_items')
                .update({ barcode: newBarcodeClean })
                .eq('barcode', oldBarcode)
                .in('role', rolesToUpdate);
             if (error) throw error;
          }

          alert('Barcode berhasil diubah.');
          await fetchTrackingData();
       } catch (err: any) {
          console.error('Error updating barcode:', err);
          alert('Gagal mengubah barcode: ' + err.message);
       }
    };

    const handleDeleteBarcodesFromCompareCol = async (col: 'BATCH' | 'PICKER' | 'CHECKER' | 'PACKING', barcodes: string[]) => {
       if (barcodes.length === 0) return;
       
       let colName = '';
       if (col === 'BATCH') colName = 'Total Resi Batch';
       else if (col === 'PICKER') colName = 'Scanned Picker/Ojol';
       else if (col === 'CHECKER') colName = 'Scanned Checker';
       else if (col === 'PACKING') colName = 'Fully Packed (Packing)';

       if (!window.confirm(`Yakin ingin menghapus ${barcodes.length} data scan/resi dari sumber "${colName}" di database?\nTindakan ini tidak dapat dibatalkan.`)) {
          return;
       }

       try {
          if (col === 'BATCH') {
             const { error } = await supabase
                .from('batch_items')
                .delete()
                .in('barcode', barcodes);
             if (error) throw error;
          } else {
             const rolesToDelete = col === 'PICKER' ? ['PICKER', 'PICKER_2', 'OJOL'] : [col];
             const { error } = await supabase
                .from('scanned_items')
                .delete()
                .in('barcode', barcodes)
                .in('role', rolesToDelete);
             if (error) throw error;
          }

          alert(`Berhasil menghapus ${barcodes.length} data.`);
          if (col === compareColA) setSelectedCompareA([]);
          else setSelectedCompareB([]);
          await fetchTrackingData();
       } catch (err: any) {
          console.error('Error deleting comparison items:', err);
          alert('Gagal menghapus data: ' + err.message);
       }
    };

    const handleDeleteSelectedTrackingBarcodes = async () => {
       if (selectedTrackingBarcodes.length === 0) return;
       if (!window.confirm(`Yakin ingin menghapus ${selectedTrackingBarcodes.length} resi terpilih dari database (batch_items & scanned_items)?\n\nTindakan ini tidak dapat dibatalkan.`)) {
          return;
       }

       setIsDeletingTrackingBarcodes(true);
       try {
          const CHUNK_SIZE = 500;
          for (let i = 0; i < selectedTrackingBarcodes.length; i += CHUNK_SIZE) {
             const chunk = selectedTrackingBarcodes.slice(i, i + CHUNK_SIZE);
             
             // 1. Delete from batch_items
             const { error: batchErr } = await supabase
                .from('batch_items')
                .delete()
                .in('barcode', chunk);
             if (batchErr) throw batchErr;

             // 2. Delete from scanned_items
             const { error: scanErr } = await supabase
                .from('scanned_items')
                .delete()
                .in('barcode', chunk);
             if (scanErr) throw scanErr;
          }

          setSuccessToast(`Berhasil menghapus ${selectedTrackingBarcodes.length} resi.`);
          setSelectedTrackingBarcodes([]);
          await fetchTrackingData();
       } catch (err: any) {
          console.error("Error deleting selected tracking barcodes:", err);
          alert("Gagal menghapus data resi: " + err.message);
       } finally {
          setIsDeletingTrackingBarcodes(false);
       }
    };

    // Reset trackingPage on filter change
    useEffect(() => {
       setTrackingPage(1);
    }, [trackingSearchQuery, filterDate]);

    // Memoized comparison calculations for Tracking Resi
    const { onlyInA, onlyInB } = useMemo(() => {
       if (!isCompareModalOpen || trackResiList.length === 0) {
          return { onlyInA: [], onlyInB: [] };
       }

       const getBarcodesForColumn = (col: 'BATCH' | 'PICKER' | 'CHECKER' | 'PACKING') => {
          if (col === 'BATCH') return trackResiList.map(item => item.barcode);
          if (col === 'PICKER') return trackResiList.filter(item => item.picker).map(item => item.barcode);
          if (col === 'CHECKER') return trackResiList.filter(item => item.checker).map(item => item.barcode);
          if (col === 'PACKING') return trackResiList.filter(item => item.packing).map(item => item.barcode);
          return [];
       };

       const listA = getBarcodesForColumn(compareColA);
       const listB = getBarcodesForColumn(compareColB);

       const setA = new Set(listA.map(b => b.toUpperCase().trim()));
       const setB = new Set(listB.map(b => b.toUpperCase().trim()));

       const oA = listA.filter(x => !setB.has(x.toUpperCase().trim()));
       const oB = listB.filter(x => !setA.has(x.toUpperCase().trim()));

       return { onlyInA: oA, onlyInB: oB };
    }, [isCompareModalOpen, trackResiList, compareColA, compareColB]);

    // Memoized filtering and counting logic for TRACK_RESI list
    const { trackingFilteredList, trackingPickerCount, trackingCheckerCount, trackingPackingCount } = useMemo(() => {
       const query = trackingSearchQuery.toUpperCase().trim();
       let baseList = trackResiList;
       if (hideExpiredResi) {
          baseList = trackResiList.filter((item: any) => {
             const hasExpired = 
                (item.picker?.employee_name || '').toUpperCase().includes('RESI KEDALUWARSA') ||
                (item.checker?.employee_name || '').toUpperCase().includes('RESI KEDALUWARSA') ||
                (item.packing?.employee_name || '').toUpperCase().includes('RESI KEDALUWARSA');
             return !hasExpired;
          });
       }

       const filtered = query
          ? baseList.filter((item: any) => item.barcode.toUpperCase().includes(query))
          : baseList;
          
       let pCount = 0;
       let cCount = 0;
       let pkCount = 0;
       
       for (let i = 0; i < baseList.length; i++) {
          const item = baseList[i];
          if (item.picker) pCount++;
          if (item.checker) cCount++;
          if (item.packing) pkCount++;
       }
       
       return {
          trackingFilteredList: filtered,
          trackingPickerCount: pCount,
          trackingCheckerCount: cCount,
          trackingPackingCount: pkCount
       };
    }, [trackResiList, trackingSearchQuery, hideExpiredResi]);

    // Memoized paginated list for TRACK_RESI table
    const trackingPaginatedList = useMemo(() => {
       const from = (trackingPage - 1) * trackingRowsPerPage;
       const to = trackingPage * trackingRowsPerPage;
       return trackingFilteredList.slice(from, to);
    }, [trackingFilteredList, trackingPage, trackingRowsPerPage]);
   
