   const [oldestRecordDate, setOldestRecordDate] = useState<string | null>(null);

   const checkDataAvailability = async () => {
      setIsLoadingDebugStats(true);
      const results: { date: string; count: number }[] = [];
      try {
         // 1. Check Oldest Record (Absolute Proof)
         const { data: oldestData, error: oldestError } = await supabase
            .from('scanned_items')
            .select('timestamp')
            .order('timestamp', { ascending: true })
            .limit(1)
            .maybeSingle();

         if (oldestData && oldestData.timestamp) {
            setOldestRecordDate(new Date(oldestData.timestamp).toLocaleString('id-ID'));
         } else {
            setOldestRecordDate("NO DATA FOUND");
         }

         // 2. Scan last 30 days
         const today = new Date();
         for (let i = 0; i < 30; i++) {
            const d = new Date(today);
            d.setDate(today.getDate() - i);
            const dateStr = d.toISOString().split('T')[0];
            const start = new Date(dateStr + 'T00:00:00').getTime();
            const end = new Date(dateStr + 'T23:59:59.999').getTime();

            const { count, error } = await supabase
               .from('scanned_items')
               .select('*', { count: 'exact', head: true })
               .gte('timestamp', start)
               .lte('timestamp', end);

            if (!error) results.push({ date: dateStr, count: count || 0 });
         }
         setDebugStats(results);
      } catch (e) {
         console.error(e);
      } finally {
         setIsLoadingDebugStats(false);
      }
   };

