   // Secret Menu Listener (DevMode)
   useEffect(() => {
      const sequence = ['d', 'e', 'v', 'm', 'o', 'd', 'e', 'n', 'e', 'w'];
      let currentIndex = 0;

      const handleKeyDown = (e: KeyboardEvent) => {
         // Only trigger if typing the sequence
         if (e.key.toLowerCase() === sequence[currentIndex]) {
            currentIndex++;
            if (currentIndex === sequence.length) {
               // Sequence completed
               const newState = !showFakeReportMenu;
               setShowFakeReportMenu(newState);
               setShowSecretMenu(newState);
               setShowFsSyncDevMode(newState);
               localStorage.setItem('showFakeReportMenu', String(newState));
               localStorage.setItem('showSecretMenu', String(newState));
               setSuccessToast(newState ? "⚡ Dev Mode Secret Unlocked! (Tombol Hapus Ekstra & Feature Dev Aktif)" : "Dev Mode Deactivated");
               currentIndex = 0;
            }
         } else {
            // Reset if key doesn't match sequence
            currentIndex = 0;
         }
      };

      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
   }, [showFakeReportMenu]);

