   // --- FETCH FUNCTIONS ---
   const fetchTrackingData = async () => {
      setIsTrackingLoading(true);
      try {
         const startOfDayISO = new Date(filterDate + 'T00:00:00').toISOString();
         const endOfDayISO = new Date(filterDate + 'T23:59:59').toISOString();
         const startTs = new Date(filterDate + 'T00:00:00').getTime();
         const endTs = new Date(filterDate + 'T23:59:59').getTime();

         // 1. Fetch batches lookup map using Promise.all to bypass 1000 limit and improve speed
         const { count: totalBatches } = await supabase.from('batches').select('*', { count: 'exact', head: true });
         let allBatches: any[] = [];
         if (totalBatches) {
             const batchPromises = [];
             for (let i = 0; i < totalBatches; i += 1000) {
                 batchPromises.push(supabase.from('batches').select('excel_filename, batch_no, created_by, created_at')
                     .order('created_at', { ascending: false })
                     .range(i, i + 999));
             }
             for (let i = 0; i < batchPromises.length; i += 10) {
                 const res = await Promise.all(batchPromises.slice(i, i + 10));
                 res.forEach(r => { if (r.error) throw r.error; r.data && allBatches.push(...r.data); });
             }
         }

         const filenameToBatchInfo: Record<string, { batch_no: string; created_by: string; created_at: string }> = {};
         allBatches.forEach(b => {
            if (b.excel_filename) {
               filenameToBatchInfo[b.excel_filename] = {
                  batch_no: b.batch_no,
                  created_by: b.created_by,
                  created_at: b.created_at
               };
            }
         });

         // 2. Fetch ALL active batch items for today using loop pagination to bypass Supabase 1000 limit
         const { count: batchCount } = await supabase.from('batch_items').select('*', { count: 'exact', head: true })
               .gte('created_at', startOfDayISO).lte('created_at', endOfDayISO);
            
            let activeBatchItems: any[] = [];
            if (batchCount) {
                const promises = [];
                for (let i = 0; i < batchCount; i += 1000) {
                    promises.push(supabase.from('batch_items').select('id, barcode, created_at, batches!inner(batch_no, created_by)')
                        .gte('created_at', startOfDayISO).lte('created_at', endOfDayISO)
                        .range(i, i + 999));
                }
                for (let i = 0; i < promises.length; i += 10) {
                    const res = await Promise.all(promises.slice(i, i + 10));
                    res.forEach(r => { if (r.error) throw r.error; r.data && activeBatchItems.push(...r.data); });
                }
                activeBatchItems.sort((a,b) => {
            const timeA = typeof a.created_at === 'number' ? a.created_at : isNaN(Number(a.created_at)) ? new Date(a.created_at).getTime() : Number(a.created_at);
            const timeB = typeof b.created_at === 'number' ? b.created_at : isNaN(Number(b.created_at)) ? new Date(b.created_at).getTime() : Number(b.created_at);
            return timeA - timeB;
        });
            }

         // 3. Fetch ALL scanned items today using loop pagination to bypass Supabase 1000 limit
         const { count: scanCount } = await supabase.from('scanned_items').select('*', { count: 'exact', head: true })
               .gte('timestamp', startTs)
               .lte('timestamp', endTs);
               
            let scannedItems: any[] = [];
            if (scanCount) {
                const promises = [];
                for (let i = 0; i < scanCount; i += 1000) {
                    promises.push(supabase.from('scanned_items').select('barcode, role, employee_name, timestamp, excel_filename')
                        .gte('timestamp', startTs).lte('timestamp', endTs)
                        .range(i, i + 999));
                }
                for (let i = 0; i < promises.length; i += 10) {
                    const res = await Promise.all(promises.slice(i, i + 10));
                    res.forEach(r => { if (r.error) throw r.error; r.data && scannedItems.push(...r.data); });
                }
                // Sort in memory for performance
                scannedItems.sort((a,b) => Number(a.timestamp) - Number(b.timestamp));
            }

         // 4. Build lookup map for roles
         const scanMap: Record<string, Record<string, { employee_name: string; timestamp: number }>> = {};
         scannedItems.forEach(item => {
            if (!scanMap[item.barcode]) {
               scanMap[item.barcode] = {};
            }
            scanMap[item.barcode][item.role] = {
               employee_name: item.employee_name || '',
               timestamp: item.timestamp
            };
         });

         // 5. Gather union of all unique barcodes for today's tracking
         const allBatchBarcodes = new Set<string>();
         const barcodeToBatchMeta: Record<string, { batch_no: string; created_by: string; created_at: string }> = {};

         // Add active batch items
         activeBatchItems.forEach(item => {
            const batchesObj = Array.isArray(item.batches) ? item.batches[0] : (item.batches as any);
            allBatchBarcodes.add(item.barcode);
            barcodeToBatchMeta[item.barcode] = {
               batch_no: batchesObj?.batch_no || '',
               created_by: batchesObj?.created_by || 'Admin',
               created_at: item.created_at
            };
         });

         // Add ALL items scanned today (from scanned_items)
         scannedItems.forEach(item => {
            allBatchBarcodes.add(item.barcode);
            if (!barcodeToBatchMeta[item.barcode]) {
               const meta = item.excel_filename ? filenameToBatchInfo[item.excel_filename] : null;
               barcodeToBatchMeta[item.barcode] = {
                  batch_no: meta?.batch_no || (item.excel_filename ? item.excel_filename : 'Batch (Admin)'),
                  created_by: meta?.created_by || 'Admin',
                  created_at: meta?.created_at || new Date(item.timestamp).toISOString()
               };
            }
         });

         // 6. Merge and format list
         const mergedList = Array.from(allBatchBarcodes).map(barcode => {
            const barcodeMap = scanMap[barcode] || {};
            const pickerScan = barcodeMap['PICKER'] || barcodeMap['PICKER_2'] || barcodeMap['OJOL'] || null;
            const checkerScan = barcodeMap['CHECKER'] || null;
            const packingScan = barcodeMap['PACKING'] || null;

            const meta = barcodeToBatchMeta[barcode] || { batch_no: 'Batch (Admin)', created_by: 'Admin', created_at: startOfDayISO };

            return {
               id: barcode, // Use barcode as unique row key
               barcode: barcode,
               adminName: meta.batch_no ? `${meta.batch_no} (${meta.created_by})` : `Batch (${meta.created_by})`,
               scannedAt: meta.created_at,
               picker: pickerScan,
               checker: checkerScan,
               packing: packingScan
            };
         });

         // Order by scannedAt/createdAt descending
         mergedList.sort((a, b) => new Date(b.scannedAt).getTime() - new Date(a.scannedAt).getTime());

         setTrackResiList(mergedList);
      } catch (err: any) {
         console.error("Error fetching tracking data:", err);
      } finally {
         setIsTrackingLoading(false);
      }
   };

