   // --- EFFECTS ---

   // 1. Initial Config Load
   useEffect(() => {
      const fetchConfig = async () => {
         // CACHE: Load Config
         try {
            const cachedShifts = localStorage.getItem('app_shifts_cache');
            if (cachedShifts) {
               let shifts = JSON.parse(cachedShifts);
               // ALWAYS remove "OJOL" (uppercase) - it has no data
               shifts = shifts.filter((s: string) => s !== 'OJOL');
               setAvailableShifts(shifts);
            }
            const cachedRoles = localStorage.getItem('app_roles_cache');
            if (cachedRoles) setAvailableRoles(JSON.parse(cachedRoles));
         } catch (e) { }

         // FETCH: Background Update
         try {
            const { data: shifts, error: shiftError } = await supabase
               .from('app_shifts')
               .select('name')
               .order('name', { ascending: true });

            if (shiftError) console.error("Error fetching shifts:", shiftError);

            if (shifts) {
               let shiftNames = (shifts as any[]).map(s => s.name);

               // ALWAYS remove "OJOL" (uppercase) - it has no data
               shiftNames = shiftNames.filter(s => s !== 'OJOL');

               // Update State & Cache
               setAvailableShifts(shiftNames);
               localStorage.setItem('app_shifts_cache', JSON.stringify(shiftNames));
            }
         } catch (e) { }
         try {
              const { data: roles } = await supabase.from('app_roles').select('name');
              if (roles && roles.length > 0) {
                 const roleNames = (roles as any[]).map(r => r.name);
                 DEFAULT_ROLES.forEach(dr => {
                    if (!roleNames.includes(dr)) roleNames.push(dr);
                 });
                 setAvailableRoles(prev => {
                    if (JSON.stringify(prev) !== JSON.stringify(roleNames)) {
                       localStorage.setItem('app_roles_cache', JSON.stringify(roleNames));
                       return roleNames;
                    }
                    return prev;
                 });
            }
         } catch (e) { }
      };
      fetchConfig();
   }, []);



