   const [isCleaningDevModeJnap, setIsCleaningDevModeJnap] = useState(false);

   // NEW: DevMode Tool to format JNAP barcodes (JNAPxxxxxxxx -> JNAP-xxxxxxxxx) across all roles
   const handleCleanDevModeJnapData = async () => {
      const confirmClean = window.confirm(
         "🧹 DevMode JNAP Format Tool:\n\nApakah Anda yakin ingin memformat resi 'JNAPxxxxxxxx' menjadi 'JNAP-xxxxxxxxx' di database untuk SELURUH role?"
      );
      if (!confirmClean) return;

      setIsCleaningDevModeJnap(true);
      try {
         let allRecords: { id: string; barcode: string; role: string }[] = [];
         let offset = 0;
         const limit = 1000;

         const startOfDay = filterDate ? new Date(filterDate + 'T00:00:00.000').getTime() : 0;
         const endOfDay = filterDate ? new Date(filterDate + 'T23:59:59.999').getTime() : 0;

         while (true) {
            let q = supabase.from('scanned_items').select('id, barcode, role');
            if (startOfDay && endOfDay) {
               q = q.gte('timestamp', startOfDay).lte('timestamp', endOfDay);
            }
            q = q.ilike('barcode', 'JNAP%').order('timestamp', { ascending: true }).range(offset, offset + limit - 1);
            const { data: pageData, error } = await q;
            if (error) throw error;
            if (!pageData || pageData.length === 0) break;
            allRecords = [...allRecords, ...pageData];
            if (pageData.length < limit) break;
            offset += limit;
         }

         if (allRecords.length === 0) {
            alert("Tidak ada data resi 'JNAP' yang perlu diformat pada tanggal ini.");
            return;
         }

         const updates: { id: string; barcode: string }[] = [];
         allRecords.forEach(r => {
            const oldBarcode = (r.barcode || '').toString().trim();
            if (/^JNAP[^-]/i.test(oldBarcode)) {
               const newBarcode = 'JNAP-' + oldBarcode.substring(4);
               updates.push({ id: r.id, barcode: newBarcode });
            }
         });

         if (updates.length === 0) {
            alert(`Diperiksa ${allRecords.length} data JNAP: Seluruh data resi JNAP sudah berformat JNAP-!`);
            return;
         }

         for (let i = 0; i < updates.length; i += 100) {
            const chunk = updates.slice(i, i + 100);
            await Promise.all(
               chunk.map(u => supabase.from('scanned_items').update({ barcode: u.barcode }).eq('id', u.id))
            );
         }

         setSuccessToast(`🧹 DevMode Repair: Berhasil memformat ${updates.length} data resi JNAP (JNAP-xxxxxxxxx)!`);
         setTimeout(() => {
            window.location.reload();
         }, 1000);
      } catch (err: any) {
         console.error("Gagal memformat data resi JNAP:", err);
         alert("Gagal memformat data resi JNAP: " + (err.message || 'Error tidak diketahui'));
      } finally {
         setIsCleaningDevModeJnap(false);
      }
   };

   const handleSaveLogistikImport = async () => {
      if (!logistikImportText.trim()) {
         alert("Masukkan atau paste data resi Logistik.");
         return;
      }
      setIsSavingLogistik(true);
      try {
         const rawLines = logistikImportText.split(/[\n\r,;]+/).map(b => b.trim()).filter(Boolean);
         if (rawLines.length === 0) throw new Error("Tidak ada data barcode yang diinput.");

         // 1. Check for Forbidden Symbols (strict rejection)
         const activeSymbolsList = forbiddenSymbols.map(s => s.symbol).filter(Boolean);
         const invalidLines: string[] = [];

         rawLines.forEach(line => {
            const hasForbiddenSymbol = activeSymbolsList.some(sym => line.includes(sym));
            const hasSpecialChars = /[^a-zA-Z0-9\-\_\/\s]/.test(line);
            if (hasForbiddenSymbol || hasSpecialChars) {
               invalidLines.push(line);
            }
         });

         if (invalidLines.length > 0) {
            const sampleDisplay = invalidLines.slice(0, 15).map(l => `- "${l}"`).join('\n');
            const extraCount = invalidLines.length > 15 ? `\n...dan ${invalidLines.length - 15} data lainnya` : '';
            alert(
               `❌ IMPORT LOGISTIK DITOLAK!\n\nTerdapat ${invalidLines.length} data yang mengandung SIMBOL TERLARANG:\n\nData Bermasalah:\n${sampleDisplay}${extraCount}\n\nSilakan bersihkan data tersebut dari teks import dan coba lagi.`
            );
            setIsSavingLogistik(false);
            return;
         }

         // 2. Sanitize & pad valid barcodes
         const cleanedBarcodes = rawLines.map(line => sanitizeAndPadBarcode(line)).filter(Boolean);
         const uniqueBarcodes = Array.from(new Set(cleanedBarcodes));
         if (uniqueBarcodes.length === 0) throw new Error("Tidak ada barcode valid setelah sanitasi.");

         const targetTimestamp = logistikImportDate ? (() => {
            const [y, m, d] = logistikImportDate.split('-').map(Number);
            const dateObj = new Date();
            dateObj.setFullYear(y, m - 1, d);
            const now = new Date();
            dateObj.setHours(now.getHours(), now.getMinutes(), now.getSeconds(), now.getMilliseconds());
            return dateObj.getTime();
         })() : Date.now();

         const insertChunkSize = 500;
         for (let i = 0; i < uniqueBarcodes.length; i += insertChunkSize) {
            const chunk = uniqueBarcodes.slice(i, i + insertChunkSize);
            const insertData = chunk.map(barcode => {
               const uniqueId = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
               return {
                  id: uniqueId,
                  barcode,
                  timestamp: targetTimestamp,
                  status: 'OK',
                  menu_context: 'LOGISTIK',
                  role: 'LOGISTIK',
                  employee_name: 'LOGISTIK',
                  user_email: currentAdmin?.username || 'admin@kalindo.com',
               };
            });
            const { error } = await supabase.from('scanned_items').insert(insertData);
            if (error) throw error;
         }

         setSuccessToast(`Berhasil mengimpor ${uniqueBarcodes.length} data Logistik pada tanggal ${logistikImportDate}.`);
         setLogistikImportText('');
         const today = new Date();
         const offset = today.getTimezoneOffset() * 60000;
         setLogistikImportDate((new Date(today.getTime() - offset)).toISOString().slice(0, 10));
         setIsLogistikImportModalOpen(false);
         // Refresh data logistik
         if (activeView === 'LOGISTIK_DATA') {
            fetchPackingData(1);
         }
      } catch (err: any) {
         alert("Gagal mengimpor Logistik: " + err.message);
      } finally {
         setIsSavingLogistik(false);
      }
   };

   const processBulkExcelUpload = async () => {
      if (excelFilesToImport.length === 0) {
         alert("Pilih minimal satu file Excel.");
         return;
      }

      setIsLoadingBatchData(true);
      let totalImported = 0;
      let sheetsProcessed = 0;
      let filesProcessed = 0;
      let errors: string[] = [];

      try {
         for (const file of excelFilesToImport) {
            try {
               const data = await file.arrayBuffer();
               const workbook = XLSX.read(new Uint8Array(data), { type: 'array' });
               
               let targetSheets = workbook.SheetNames.filter(name => name.toLowerCase().startsWith('batch'));
               if (targetSheets.length === 0) {
                  targetSheets = workbook.SheetNames; // Allow any sheet name if 'Batch' is not found
               }

               // Generate shared identity parts
               const datePart = new Date().toISOString().slice(0, 10).replace(/-/g, '');
               const randomPart = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
               const baseFileName = file.name.replace(/\.[^/.]+$/, ""); // strip extension

               for (const sheetName of targetSheets) {
                  const worksheet = workbook.Sheets[sheetName];
                  const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 }) as any[][];

                  if (jsonData.length === 0) continue;

                  // Map to group items by batch name
                  const batchGroups = new Map<string, { barcode: string; order_id: string | null }[]>();

                  // Try to find the AWB, Batch, and Order ID columns dynamically from header (index 0)
                  const headerRow = jsonData[0] || [];
                  let awbIndex = -1;
                  let batchIndex = -1;
                  let orderIdIndex = -1;
                  
                  for (let col = 0; col < headerRow.length; col++) {
                     const colName = String(headerRow[col] || '').toUpperCase().trim();
                     if (colName.includes('AWB') || colName.includes('BARCODE') || colName.includes('RESI')) {
                        awbIndex = col;
                     }
                     if (colName.includes('BATCH') || colName.includes('FILENAME')) {
                        batchIndex = col;
                     }
                     if (colName.includes('PESANAN') || colName.includes('ORDER_ID') || colName.includes('ORDER ID') || colName === 'ID') {
                        orderIdIndex = col;
                     }
                  }

                  if (awbIndex === -1) awbIndex = 3; // Default to column D (index 3) if not found

                  // Skip index 0 (header D1). Start from index 1 (D2)
                  for (let i = 1; i < jsonData.length; i++) {
                     const row = jsonData[i];
                     if (row && row.length > awbIndex && row[awbIndex]) {
                        const bc = formatBarcodeWithKnownPrefixes(String(row[awbIndex]).replace(/@/g, '').trim().toUpperCase());
                        const ordId = (orderIdIndex !== -1 && row[orderIdIndex]) ? String(row[orderIdIndex]).replace(/@/g, '').trim().toUpperCase() : null;
                        if (bc) {
                           let rowBatchName = `${sheetName.trim()} [${baseFileName}]-${datePart}-${randomPart}`;
                           if (batchIndex !== -1 && row[batchIndex]) {
                              rowBatchName = String(row[batchIndex]).trim();
                           }

                           if (!batchGroups.has(rowBatchName)) {
                              batchGroups.set(rowBatchName, []);
                           }
                           batchGroups.get(rowBatchName)!.push({ barcode: bc, order_id: ordId });
                        }
                     }
                  }

                  // Process each grouped batch
                  for (const [batchNo, rawItems] of batchGroups.entries()) {
                     // Remove duplicates within the batch based on barcode
                     const uniqueMap = new Map<string, { barcode: string; order_id: string | null }>();
                     for (const it of rawItems) {
                        if (!uniqueMap.has(it.barcode)) {
                           uniqueMap.set(it.barcode, it);
                        }
                     }
                     const uniqueItems = Array.from(uniqueMap.values());
                     if (uniqueItems.length === 0) continue;

                     let batchId;
                     const { data: newBatch, error: batchError } = await supabase
                        .from('batches')
                        .insert({
                           batch_no: batchNo,
                           created_by: currentAdmin?.username || 'admin'
                        })
                        .select()
                        .single();

                     if (batchError) {
                        console.error(`Batch error on sheet ${sheetName}, batch ${batchNo}:`, batchError);
                        continue; // Skip the error batch but continue others
                     }
                     batchId = newBatch.id;

                     // Enforce unique Barcode/AWB logic (Filter out barcodes that already exist in any batch)
                     const existingSet = new Set<string>();
                     const CHUNK_SIZE = 500;

                     const allBarcodes = uniqueItems.map(it => it.barcode);
                     for (let i = 0; i < allBarcodes.length; i += CHUNK_SIZE) {
                        const chunk = allBarcodes.slice(i, i + CHUNK_SIZE);
                        const { data: matched } = await supabase
                           .from('batch_items')
                           .select('barcode')
                           .in('barcode', chunk);

                        if (matched) {
                           matched.forEach((m: any) => existingSet.add(m.barcode as string));
                        }
                     }

                     const finalItemsToInsert = uniqueItems.filter(it => !existingSet.has(it.barcode));

                     if (finalItemsToInsert.length === 0) continue; // Skip if all barcodes already imported

                     // Insert only completely new barcodes via chunks
                     const INSERT_CHUNK = 500;
                     for (let i = 0; i < finalItemsToInsert.length; i += INSERT_CHUNK) {
                        const insertChunk = finalItemsToInsert.slice(i, i + INSERT_CHUNK);
                        const { error: itemsError } = await supabase.from('batch_items').insert(
                           insertChunk.map(item => ({
                              batch_id: batchId,
                              barcode: item.barcode,
                              order_id: item.order_id || null
                           }))
                        );

                        if (itemsError) {
                           console.error(`Items error on sheet ${sheetName}, batch ${batchNo} (chunk):`, itemsError);
                        }
                     }

                     totalImported += finalItemsToInsert.length;
                     sheetsProcessed++;

                     // Save to Firestore admin_batch_imports for each batch
                     const upperFilename = file.name.toUpperCase();
                     const matchedStaff = STAFF_NAMES.find(staff => upperFilename.includes(staff)) || 'LAINNYA';
                     try {
                        await addDoc(collection(db, 'admin_batch_imports'), {
                           excelFilename: file.name,
                           staffName: matchedStaff,
                           jumlah: finalItemsToInsert.length,
                           timestamp: new Date().toISOString(),
                           batchId: batchNo,
                           createdAt: new Date().toISOString(),
                           barcodes: finalItemsToInsert.map(i => i.barcode)
                        });
                     } catch (fsErr: any) {
                        console.error("Failed to save to Firestore admin_batch_imports:", fsErr);
                     }
                  }
               }
               filesProcessed++;
            } catch (fileErr: any) {
               errors.push(`File ${file.name}: ${fileErr.message}`);
            }
         }

         if (totalImported > 0) {
            setSuccessToast(`Berhasil mengimpor ${totalImported} barcode dari ${sheetsProcessed} sheet (${filesProcessed} file Excel).`);
            fetchBatchData();
            setAdminImportsTrigger(prev => prev + 1);
            setIsExcelImportModalOpen(false);
            setExcelFilesToImport([]);
         } else if (errors.length > 0) {
            alert(`Tidak ada barcode yang diimpor.\nKesalahan:\n${errors.join('\n')}`);
         } else {
            alert("Tidak ada barcode yang valid ditemukan di kolom D (D2 ke bawah) pada file terpilih.");
         }
      } catch (err: any) {
         alert("Gagal memproses file Excel: " + err.message);
      } finally {
         setIsLoadingBatchData(false);
      }
   };

