   const handleBulkMoveDateBatchSummaryConfirm = async () => {
      if (!moveBatchSummaryDate) {
         alert('Pilih tanggal terlebih dahulu!');
         return;
      }
      
      const totalToMove = selectedBatchSummaryIds.length;
      if (!window.confirm(`Pindahkan tanggal ${totalToMove} batch yang dipilih ke ${moveBatchSummaryDate}? (Semua data barcode di dalam batch juga akan ikut pindah)`)) return;

      setIsLoadingBatchSummary(true);
      try {
         const dateObj = new Date();
         const [y, m, d] = moveBatchSummaryDate.split('-');
         dateObj.setFullYear(parseInt(y), parseInt(m) - 1, parseInt(d));
         const overrideCreatedAt = dateObj.toISOString();

         const idsToMove = selectedBatchSummaryIds;
         
         // Fetch batch numbers to sync with Firestore admin_batch_imports
         const { data: batchesToSync } = await supabase
            .from('batches')
            .select('id, batch_no')
            .in('id', idsToMove);

         const batchNoArr = (batchesToSync || []).map(b => b.batch_no).filter(Boolean);

         // Move in chunks for batches in Supabase
         for (let i = 0; i < idsToMove.length; i += 500) {
            const chunk = idsToMove.slice(i, i + 500);
            const { error: moveErr } = await supabase.from('batches').update({ created_at: overrideCreatedAt }).in('id', chunk);
            if (moveErr) throw moveErr;
            // cascade to batch_items
            const { error: moveItemsErr } = await supabase.from('batch_items').update({ created_at: overrideCreatedAt }).in('batch_id', chunk);
            if (moveItemsErr) throw moveItemsErr;
         }

         // Sync Firestore admin_batch_imports for these batch numbers
         try {
            for (let i = 0; i < batchNoArr.length; i += 10) {
               const chunk = batchNoArr.slice(i, i + 10);
               if (chunk.length === 0) continue;
               const fsQ = fsQuery(collection(db, 'admin_batch_imports'), where('batchId', 'in', chunk));
               const fsSnap = await getDocs(fsQ);
               const b = writeBatch(db);
               fsSnap.forEach(docSnap => {
                  b.update(docSnap.ref, { timestamp: overrideCreatedAt });
               });
               await b.commit();
            }
         } catch (fsErr) {
            console.error("Failed to sync Firestore batch dates:", fsErr);
         }

         setSuccessToast(`${totalToMove} batch beserta isinya berhasil dipindah tanggalnya.`);
         setSelectedBatchSummaryIds([]);
         setIsMoveDateBatchSummaryModalOpen(false);
         setRefreshSummaryTrigger(prev => prev + 1);
         setAdminImportsTrigger(prev => prev + 1);
      } catch (err: any) {
         alert("Gagal memindahkan tanggal batch: " + err.message);
      } finally {
         setIsLoadingBatchSummary(false);
      }
   };

