   const handleForceAssignPicker = async (employeeName: string) => {
      const totalToAssign = selectedBatchSummaryIds.length;
      if (!window.confirm(`Force autocomplete ${totalToAssign} batch(es) for picker ${employeeName}?`)) return;

      setIsForceAssignLoading(true);
      try {
         const idsToAssign = selectedBatchSummaryIds;
         
         // 1. Get all items in selected batches
         const { data: batchItems, error: itemsErr } = await supabase
            .from('batch_items')
            .select('barcode')
            .in('batch_id', idsToAssign);
            
         if (itemsErr) throw itemsErr;
         if (!batchItems || batchItems.length === 0) {
            alert("No items found in selected batches.");
            setIsForceAssignLoading(false);
            return;
         }

         const barcodes = batchItems.map(item => item.barcode).filter(b => b);

         // 2. Fetch existing scanned_items to prevent duplicates
         const { data: existingScans, error: existErr } = await supabase
            .from('scanned_items')
            .select('barcode')
            .in('barcode', barcodes)
            .eq('role', 'PICKER');
            
         if (existErr) throw existErr;
         const existingBarcodes = new Set((existingScans || []).map(s => s.barcode));

         // 3. Filter missing barcodes
         const missingBarcodes = barcodes.filter(b => !existingBarcodes.has(b));
         
         if (missingBarcodes.length === 0) {
            alert(`Semua item (${barcodes.length} barcode) dalam batch ini sudah ter-scan oleh Picker! Tidak ada yang kurang.`);
            setIsForceAssignModalOpen(false);
            setIsForceAssignLoading(false);
            return;
         }

         // 4. Insert missing barcodes as PICKER scans
         const insertPayload = missingBarcodes.map((barcode, index) => ({
            id: `scan-${Date.now()}-${index}-${Math.random().toString(36).substring(2, 9)}`,
            barcode,
            role: 'PICKER',
            timestamp: Date.now(),
            menu_context: 'PICKER_DASHBOARD',
            employee_name: employeeName,
            user_email: 'admin_force_assign@system'
         }));
         
         // Batch insert (chunking to avoid payload too large)
         for (let i = 0; i < insertPayload.length; i += 100) {
            const chunk = insertPayload.slice(i, i + 100);
            const { error: insErr } = await supabase.from('scanned_items').insert(chunk);
            if (insErr) throw insErr;
         }
         
         setSuccessToast(`Successfully assigned ${missingBarcodes.length} missing items to ${employeeName}`);
         setIsForceAssignModalOpen(false);
         // UI will update upon manual refresh or navigation
      } catch (err: any) {
         console.error("Force assign error:", err);
         alert("Error force assigning: " + err.message);
      } finally {
         setIsForceAssignLoading(false);
      }
   };

