   // --- CANCEL DATA FUNCTIONS ---
   const fetchCancelledOrders = async () => {
      setIsLoadingCancelData(true);
      try {
         const targetDate = (activeView === 'BATCH_DATA' || activeView === 'BATCH_DATA_2' || activeView === 'BATCH_DATA_3') ? batchDateFilter : cancelDateFilter;
         if (!targetDate) {
            setCancelledOrders([]);
            return;
         }
         const startOfDay = new Date(targetDate + 'T00:00:00').toISOString();
         const endOfDay = new Date(targetDate + 'T23:59:59.999').toISOString();

         const isBatchView = activeView === 'BATCH_DATA' || activeView === 'BATCH_DATA_2' || activeView === 'BATCH_DATA_3';
         let queryBuilder = supabase
            .from('cancelled_orders')
            .select('*')
            .eq('is_active', true)
            .gte('cancelled_at', startOfDay);

         if (!isBatchView) {
            queryBuilder = queryBuilder.lte('cancelled_at', endOfDay);
         }

         const { data, error } = await queryBuilder.order('cancelled_at', { ascending: false });
         if (error) {
            if (error.code !== '42P01') throw error; // Ignore missing table error
         }
         setCancelledOrders(data || []);
      } catch (err: any) {
         console.error("Error fetching cancelled orders:", err);
      } finally {
         setIsLoadingCancelData(false);
      }
   };

   const addCancelledOrder = async () => {
      if (!newCancelBarcode.trim()) return;
      setIsSavingCancelData(true);
      try {
         const barcode = newCancelBarcode.trim().toUpperCase();

         // Check if exists (Case Insensitive)
         const { data: existing } = await supabase
            .from('cancelled_orders')
            .select('id')
            .ilike('barcode', barcode)
            .limit(1); // Use limit 1 instead of maybeSingle to avoid errors if duplicates already exist

         if (existing && existing.length > 0) {
            alert('Barcode ini sudah ada di daftar cancel (Duplikat).');
            setIsSavingCancelData(false);
            return;
         }

         const { error } = await supabase.from('cancelled_orders').insert([{
            barcode: barcode,
            cancelled_by: currentAdmin?.username || 'Unknown',
            reason: cancelReason.trim() || null,
            is_active: true
         }]);

         if (error) throw error;

         setNewCancelBarcode('');
         fetchCancelledOrders();
         setSuccessToast('Barcode cancel berhasil ditambahkan');
      } catch (err: any) {
         alert('Gagal menambah data cancel: ' + err.message);
      } finally {
         setIsSavingCancelData(false);
      }
   };

   const addBulkCancelledOrders = async () => {
      const lines = bulkCancelBarcodes.split(/[\n,;]+/).map(line => line.trim().toUpperCase()).filter(line => line.length > 0);
      if (lines.length === 0) {
         alert('Tidak ada barcode yang valid untuk ditambahkan.');
         return;
      }

      setIsSavingCancelData(true);
      let successCount = 0;
      let duplicateCount = 0;
      let errorCount = 0;

      try {
         for (const barcode of lines) {
            // Check if exists (Case Insensitive)
            const { data: existing } = await supabase
               .from('cancelled_orders')
               .select('id')
               .ilike('barcode', barcode)
               .limit(1);

            if (existing && existing.length > 0) {
               duplicateCount++;
               continue;
            }

            const { error } = await supabase.from('cancelled_orders').insert([{
               barcode: barcode,
               cancelled_by: currentAdmin?.username || 'Unknown',
               reason: cancelReason.trim() || null,
               is_active: true
            }]);

            if (error) {
               errorCount++;
            } else {
               successCount++;
            }
         }

         setBulkCancelBarcodes('');
         fetchCancelledOrders();

         let message = `${successCount} barcode berhasil ditambahkan.`;
         if (duplicateCount > 0) message += ` ${duplicateCount} duplikat diabaikan.`;
         if (errorCount > 0) message += ` ${errorCount} gagal.`;
         setSuccessToast(message);
      } catch (err: any) {
         alert('Gagal menambah data cancel: ' + err.message);
      } finally {
         setIsSavingCancelData(false);
      }
   };

   const deleteCancelledOrder = async (id: string) => {
      if (!window.confirm('Hapus data cancel ini?')) return;
      try {
         const { error } = await supabase.from('cancelled_orders').delete().eq('id', id);
         if (error) throw error;
         setCancelledOrders(prev => prev.filter(o => o.id !== id));
         setSelectedCancelIds(prev => prev.filter(sid => sid !== id));
         setSuccessToast('Data cancel berhasil dihapus');
      } catch (err: any) {
         alert('Gagal menghapus: ' + err.message);
      }
   };

   const bulkDeleteCancelledOrders = async () => {
      if (selectedCancelIds.length === 0) return;
      setIsDeletingCancelBulk(true);
      try {
         // Get barcode list for logging
         const itemsToDelete = cancelledOrders.filter(o => selectedCancelIds.includes(o.id));
         const barcodeList = itemsToDelete.map(o => o.barcode);
         const deletedBy = currentAdmin?.username || 'Unknown Admin';

         // Log to cancel_deletion_log table (audit trail)
         try {
            await supabase.from('cancel_deletion_log').insert([{
               deleted_by: deletedBy,
               deleted_count: barcodeList.length,
               barcodes: barcodeList,
               deleted_at: new Date().toISOString()
            }]);
         } catch (logErr) {
            console.warn('Failed to log deletion (table may not exist):', logErr);
         }

         // Delete in chunks of 500
         for (let i = 0; i < selectedCancelIds.length; i += 500) {
            const chunk = selectedCancelIds.slice(i, i + 500);
            const { error } = await supabase.from('cancelled_orders').delete().in('id', chunk);
            if (error) throw error;
         }

         setCancelledOrders(prev => prev.filter(o => !selectedCancelIds.includes(o.id)));
         setSuccessToast(`${selectedCancelIds.length} data cancel berhasil dihapus oleh ${deletedBy}`);
         setSelectedCancelIds([]);
         setIsDeleteCancelModalOpen(false);
      } catch (err: any) {
         alert('Gagal menghapus data: ' + err.message);
      } finally {
         setIsDeletingCancelBulk(false);
      }
   };

   const [failedScansPage, setFailedScansPage] = useState(1);
   const [failedScansRowsPerPage, setFailedScansRowsPerPage] = useState(100);
   const [failedScansTotalRows, setFailedScansTotalRows] = useState(0);
   const [availableFailMessages, setAvailableFailMessages] = useState<string[]>([]);
   const [failedScansMessageFilter, setFailedScansMessageFilter] = useState('ALL');
   const [isMessageFilterOpen, setIsMessageFilterOpen] = useState(false);
   const [messageSearchTerm, setMessageSearchTerm] = useState('');
   const [messageHighlightIndex, setMessageHighlightIndex] = useState(0);

   const [failedScansSearch, setFailedScansSearch] = useState('');
   const [failedScansStaffFilter, setFailedScansStaffFilter] = useState('ALL');
   const [failedScansRoleFilter, setFailedScansRoleFilter] = useState('ALL');

   // Filtered Fail Messages for Searchable Dropdown
   const filteredFailMessages = useMemo(() => {
      if (!messageSearchTerm.trim()) return ['ALL', ...availableFailMessages];
      return ['ALL', ...availableFailMessages].filter(msg =>
         msg === 'ALL' || msg.toLowerCase().includes(messageSearchTerm.toLowerCase())
      );
   }, [availableFailMessages, messageSearchTerm]);

   // Fetch distinct failure messages for the filter dropdown
   const fetchUniqueFailMessages = async () => {
      try {
         const effectiveDate = filterDate || getTodayString();
         const start = new Date(effectiveDate + 'T00:00:00').getTime();
         const end = new Date(effectiveDate + 'T23:59:59.999').getTime();

         // We fetch distinct messages for the currently selected date context
         const { data, error } = await supabase
            .from('failed_scans')
            .select('fail_message')
            .gte('timestamp', start)
            .lte('timestamp', end);

         if (error) throw error;

         if (data) {
            // Extract unique messages
            const messages = Array.from(new Set(data.map(item => item.fail_message).filter(Boolean)));
            setAvailableFailMessages(messages);
         }
      } catch (error) {
         console.error("Error fetching unique messages:", error);
      }
   };

   // Update unique messages whenever the date filter changes
   useEffect(() => {
      if (hasPermission('view_failed_scans')) {
         fetchUniqueFailMessages();
      }
   }, [filterDate]);

   // Fetch Scans whenever Date, Page, or Pagination changes
   useEffect(() => {
      if (hasPermission('view_failed_scans')) {
         fetchFailedScansFilters();
         fetchFailedScans();
      }
   }, [filterDate, failedScansPage, failedScansRowsPerPage, failedScansRoleFilter, failedScansStaffFilter, failedScansSearch, failedScansMessageFilter]);

   const fetchFailedScansFilters = async () => {
      try {
         // Get Distinct Staff Names from failed_scans
         const { data: staffData } = await supabase
            .from('failed_scans')
            .select('employee_name');

         if (staffData) {
            const uniqueStaff = Array.from(new Set(staffData.map(d => d.employee_name).filter(Boolean))).sort();
            setFailedScansStaffList(uniqueStaff);
         }

         // Get Distinct Roles from failed_scans
         const { data: roleData } = await supabase
            .from('failed_scans')
            .select('role');

         if (roleData) {
            const uniqueRoles = Array.from(new Set(roleData.map(d => d.role).filter(Boolean))).sort();
            setFailedScansRoleList(uniqueRoles);
         }
      } catch (err) {
         console.error("Error fetching failed scans filters:", err);
      }
   };


   const fetchFailedScans = async () => {
      if (!hasPermission('view_failed_scans')) return;
      setIsLoadingFailedScans(true);
      try {


         const effectiveDate = filterDate || getTodayString();
         const start = new Date(effectiveDate + 'T00:00:00').getTime();
         const end = new Date(effectiveDate + 'T23:59:59.999').getTime();

         let query = supabase
            .from('failed_scans')
            .select('*', { count: 'exact' })
            .gte('timestamp', start)
            .lte('timestamp', end);

         // Apply Message Filter
         if (failedScansMessageFilter !== 'ALL') {
            query = query.eq('fail_message', failedScansMessageFilter);
         }

         // Apply Role Filter
         if (failedScansRoleFilter !== 'ALL') {
            query = query.eq('role', failedScansRoleFilter);
         }

         // Apply Staff Filter
         if (failedScansStaffFilter !== 'ALL') {
            query = query.eq('employee_name', failedScansStaffFilter);
         }

         // Apply Search (Barcode, Name, Message)
         if (failedScansSearch) {
            query = query.or(`barcode.ilike.%${failedScansSearch}%,employee_name.ilike.%${failedScansSearch}%,fail_message.ilike.%${failedScansSearch}%`);
         }

         const from = (failedScansPage - 1) * failedScansRowsPerPage;
         const to = from + failedScansRowsPerPage - 1;

         const { data, error, count } = await query
            .order('timestamp', { ascending: false })
            .range(from, to);

         if (error) throw error;
         setFailedScansData(data || []);
         setFailedScansTotalRows(count || 0);
      } catch (err: any) {
         console.error("Error fetching failed scans:", err);
      } finally {
         setIsLoadingFailedScans(false);
      }
   };

   const handleResendFailedScans = async () => {
      if (selectedFailedScanIds.length === 0) return;
      if (!confirm(`Resend ${selectedFailedScanIds.length} items? This will move them to legitimate Scanned Items.`)) return;

      setIsResending(true);
      try {
         const itemsToResend = failedScansData.filter((i: any) => selectedFailedScanIds.includes(i.id));
         const successfulIds: string[] = [];
         const newAlerts: string[] = [];

         for (const item of itemsToResend) {
            // Check if it already exists as success in scanned_items (Duplicate check)
            const { data: duplicate } = await supabase
               .from('scanned_items')
               .select('employee_name')
               .eq('barcode', item.barcode)
               //.eq('role', item.role) // Optional: strict role check or just barcode check? Usually barcode+role matters.
               .limit(1)
               .maybeSingle();

            if (duplicate) {
               newAlerts.push(`${item.barcode}: Already exists (Duplicate).`);
               continue;
            }

            const newId = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

            // Insert into scanned_items
            const { error: insertError } = await supabase.from('scanned_items').insert([{
               id: newId,
               timestamp: Date.now(), // Use NOW for resend, as it is a new valid transaction
               barcode: item.barcode,
               role: item.role,
               user_email: item.user_email,
               employee_name: item.employee_name,
               destination: item.destination || null,
               description: item.description || 'Resent from Failed Scans',
               priority: item.priority || 'NORMAL',
               status: 'COMPLETED'
            }]);

            if (!insertError) {
               // Delete from failed_scans
               await supabase.from('failed_scans').delete().eq('id', item.id);
               successfulIds.push(item.id);
            } else {
               newAlerts.push(`${item.barcode}: ${insertError.message}`);
            }
         }

         if (successfulIds.length > 0) {
            setSuccessToast(`Successfully resent ${successfulIds.length} items.`);

            // Optimistic Update
            setFailedScansData(prev => prev.filter((i: any) => !successfulIds.includes(i.id)));
            setFailedScansTotalRows(prev => prev - successfulIds.length);
            setSelectedFailedScanIds([]);
         }

         if (newAlerts.length > 0) {
            alert(`Completed with some issues:\n${newAlerts.slice(0, 10).join('\n')}${newAlerts.length > 10 ? '\n...and more' : ''}`);
         }

      } catch (err: any) {
         alert("Global error during resend: " + err.message);
      } finally {
         setIsResending(false);
      }
   };


   const handleRangeDeleteRequest = (targetView: AdminView, label: string) => {
      setDeleteTargetView(targetView);
      setDeleteTargetLabel(label);
      setDeletePin('');
      setIsDeleteModalOpen(true);
   };

   const confirmRangeDelete = async () => {
      if (deletePin !== '101010') {
         alert("PIN Salah! Akses ditolak.");
         return;
      }

      if (!deleteTargetView || isDeletingRange) return;

      if (!window.confirm(`PERINGATAN TERAKHIR!\n\nAnda akan menghapus data ${deleteTargetLabel} dari tanggal ${exportStartDate} sampai ${exportEndDate}.\n\nTindakan ini TIDAK BISA DIBATALKAN.\n\nLanjutkan?`)) {
         return;
      }

      setIsDeletingRange(true);
      try {
         const { data: empData } = await supabase.from('employees').select('name, shift');
         const shiftToNamesMap: Record<string, string[]> = {};
         if (empData) {
            empData.forEach((e: any) => {
               if (e.name && e.shift) {
                  if (!shiftToNamesMap[e.shift]) shiftToNamesMap[e.shift] = [];
                  shiftToNamesMap[e.shift].push(e.name);
               }
            });
         }

         const start = new Date(exportStartDate + 'T00:00:00');
         const end = new Date(exportEndDate + 'T23:59:59.999');

         let targetRole = '';
         let targetContext: string | null = null;

         if (deleteTargetView === 'OJOL_DATA') {
            targetRole = 'OJOL';
         } else {
            if (deleteTargetView === 'PACKING_DATA') targetRole = 'PACKING';
            else if (deleteTargetView === 'SORTIR_DATA') targetRole = 'SORTIR';
            else if (deleteTargetView === 'PICKER_DATA') targetRole = 'PICKER';
            else if (deleteTargetView === 'LOGISTIK_DATA') targetRole = 'LOGISTIK';
            else if (deleteTargetView === 'CHECKER_DATA') targetRole = 'CHECKER';
            else if (deleteTargetView === 'LEADER_2_DATA') targetRole = 'LEADER_2';
            else {
               // All GUDANG Variants
               targetRole = 'GUDANG';
               if (deleteTargetView === 'GUDANG_PENDING') targetContext = 'PENDING';
               if (deleteTargetView === 'GUDANG_CANCEL') targetContext = 'CANCEL';
               else if (deleteTargetView === 'GUDANG_READY') targetContext = 'READY';
               else if (deleteTargetView === 'GUDANG_REPORT') targetContext = 'REPORT';
               else if (deleteTargetView === 'GUDANG_BUNDLING') targetContext = 'BUNDLING';
            }
         }

         let error;
         if (targetRole === 'LEADER_2') {
            const { error: leaderErr } = await supabase.from('leader_scan_2')
               .delete()
               .gte('timestamp', start.getTime())
               .lte('timestamp', end.getTime());
            error = leaderErr;
         } else {
            const { error: rpcErr } = await supabase.rpc('admin_delete_scanned_items', {
               min_ts: start.getTime(),
               max_ts: end.getTime(),
               target_role: targetRole,
               target_context: targetContext
            });
            error = rpcErr;
         }

         if (error) throw error;

         alert(`Data ${deleteTargetLabel} berhasil dihapus!`);
         setIsDeleteModalOpen(false);
         setDeletePin('');

      } catch (err: any) {
         alert("Gagal menghapus data: " + err.message);
      } finally {
         setIsDeletingRange(false);
      }
   };

   const handleRangeExport = async (targetView: AdminView, label: string) => {
      if (isExportingRange || isLoadingPacking || isLoadingOjol) return;

      setIsExportingRange(true);
      setExportProgress(0);
      try {
         const { data: empData } = await supabase.from('employees').select('name, shift');
         const shiftMap = new Map<string, string>();
         const shiftToNamesMap: Record<string, string[]> = {};
         if (empData) {
            empData.forEach((e: any) => {
               if (e.name && e.shift) {
                  shiftMap.set(e.name, e.shift);
                  if (!shiftToNamesMap[e.shift]) shiftToNamesMap[e.shift] = [];
                  shiftToNamesMap[e.shift].push(e.name);
               }
            });
         }

         // Determine Query Builder
         let query: any;
         let countQuery: any;

         if (targetView === 'OJOL_DATA') {
            query = buildOjolQuery(shiftToNamesMap, false, { startDate: exportStartDate, endDate: exportEndDate });
            countQuery = buildOjolQuery(shiftToNamesMap, true, { startDate: exportStartDate, endDate: exportEndDate });
         } else {
            // For Packing/Sortir/Gudang
            query = buildPackingQuery(shiftToNamesMap, null, { startDate: exportStartDate, endDate: exportEndDate, overrideView: targetView });
            countQuery = buildPackingQuery(shiftToNamesMap, 'exact', { startDate: exportStartDate, endDate: exportEndDate, overrideView: targetView });
         }

         const { count, error: countError } = await countQuery.range(0, 1);
         if (countError) throw countError;
         let totalRecords = count || 0;
         
         if (totalRecords === 0 && targetView === 'PACKING_DATA') {
            try {
               const startMs = new Date(`${exportStartDate}T00:00:00`).getTime();
               const endMs = new Date(`${exportEndDate}T23:59:59.999`).getTime();

               const qFs = fsQuery(
                  collection(db, 'scanned_items'),
                  where('role', '==', 'PACKING'),
                  where('timestamp', '>=', startMs),
                  where('timestamp', '<=', endMs)
               );

               const fsSnap = await getDocs(qFs);
               let fsItems: any[] = [];
               fsSnap.forEach(docSnap => {
                  const d = docSnap.data() as Record<string, any>;
                  fsItems.push({
                     id: docSnap.id,
                     ...d,
                     employee_name: d.employee_name || d.admin_name || '-',
                     shift: shiftMap.get(d.employee_name || d.admin_name) || '-'
                  });
               });

               fsItems.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));

               if (fsItems.length > 0) {
                  const headers = "No,Timestamp,ID Pesanan,Barcode,File Excel,Employee,Shift,Role,Status,Destination,Description";
                  const batchRows = fsItems.map((item: any, idx: number) => {
                     const tsFormatted = item.timestamp ? new Date(item.timestamp).toLocaleString('id-ID').replace(/,/g, '') : '-';
                     const status = item.description?.includes('[CANCEL]') ? 'CANCEL' : 'SUCCESS';
                     return `${idx + 1},"${tsFormatted}","=""${item.order_id || ''}""","=""${item.barcode || ''}""","${item.excel_filename || ''}","${item.employee_name || ''}","${item.shift || '-'}","${item.role || 'PACKING'}","${status}","${item.destination || ''}","${(item.description || '').replace(/"/g, '""')}"`;
                  });

                  const csvContent = "\uFEFF" + headers + "\n" + batchRows.join("\n");
                  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
                  const link = document.createElement('a');
                  link.href = URL.createObjectURL(blob);
                  link.download = `Packing_Data_Firestore_${exportStartDate}_to_${exportEndDate}.csv`;
                  link.click();
                  setIsExportingRange(false);
                  return;
               }
            } catch (fsExportErr) {
               console.error("Firestore range export fallback error:", fsExportErr);
            }
         }

         if (totalRecords === 0) { alert(`No data found for ${label} in selected range.`); setIsExportingRange(false); return; }

         const FETCH_BATCH_SIZE = 1000;
         // Unlimited Export: Single File, No Split Limit

         let accumulatedRows = "";
         const headers = "No,Timestamp,ID Pesanan,Barcode,File Excel,Employee,Shift,Role,Status,Destination,Description";

         for (let offset = 0; offset < totalRecords; offset += FETCH_BATCH_SIZE) {
            setExportProgress(Math.round((offset / totalRecords) * 100));
            const to = Math.min(offset + FETCH_BATCH_SIZE - 1, totalRecords - 1);

            // Re-use builders
            let batchQuery: any;
            if (targetView === 'OJOL_DATA') {
               batchQuery = buildOjolQuery(shiftToNamesMap, false, { startDate: exportStartDate, endDate: exportEndDate });
            } else {
               batchQuery = buildPackingQuery(shiftToNamesMap, null, { startDate: exportStartDate, endDate: exportEndDate, overrideView: targetView });
            }

            const { data, error } = await batchQuery.range(offset, to);
            if (error) throw error;

            if (data && data.length > 0) {
               const enrichedBatch = data.map((item: any) => ({ ...item, shift: shiftMap.get(item.employee_name) || '-' }));
               const batchRows = enrichedBatch.map((item: any, idx: number) => {
                  const dateStr = new Date(item.timestamp).toLocaleString('id-ID');
                  // Global index
                  return `${offset + idx + 1},"${dateStr}","=""${item.order_id || ''}""","=""${item.barcode}""","${item.excel_filename || ''}","${item.employee_name}","${item.shift}","${item.role}","${item.status}","${item.destination || ''}","${item.description || ''}"`;
               }).join('\n');

               accumulatedRows += (accumulatedRows ? '\n' : '') + batchRows;

               // Small delay to prevent freeze
               await new Promise(resolve => setTimeout(resolve, 50));
            }
         }

         // Download Single File
         const blob = new Blob([headers + "\n" + accumulatedRows], { type: 'text/csv;charset=utf-8;' });
         const url = URL.createObjectURL(blob);
         const link = document.createElement('a');
         link.href = url;
         link.setAttribute('download', `${label}_${exportStartDate}_to_${exportEndDate}_ALL.csv`);
         document.body.appendChild(link);
         link.click();
         document.body.removeChild(link);

         setSuccessToast(`Export ${label} Complete!`);
         setIsExportingRange(false); // Move state reset here to ensure UI update
         setExportProgress(0);

      } catch (err: any) {
         alert("Export failed: " + err.message);
         setIsExportingRange(false);
         setExportProgress(0);
      } finally {
         // Fallback cleanup
         setTimeout(() => { if (isExportingRange) setIsExportingRange(false); }, 1000);
      }
   };



     const handleSyncChecker = async () => {
         setIsSyncingChecker(true);
         setSyncCheckerProgress(10);
         try {
            const targetDate = filterDate;
            const startTs = new Date(targetDate + 'T00:00:00').getTime();
            const endTs = new Date(targetDate + 'T23:59:59').getTime();
   
            // Priority A: Get active checkers set by Leader (checker_attendance)
            const { data: attendanceData, error: attError } = await supabase.from('checker_attendance').select('active_checkers').eq('date', targetDate);
            if (attError) throw attError;
   
            let activeCheckers: string[] = [];
            if (attendanceData && attendanceData.length > 0) {
               attendanceData.forEach(d => {
                  if (d.active_checkers) {
                     activeCheckers = [...activeCheckers, ...d.active_checkers];
                  }
               });
               activeCheckers = [...new Set(activeCheckers)].filter(Boolean);
            }

            // Priority B: Check scanned_items today for staff who actually performed CHECKER scans
            if (activeCheckers.length === 0) {
               const { data: activeScanCheckers } = await supabase
                  .from('scanned_items')
                  .select('employee_name')
                  .eq('role', 'CHECKER')
                  .gte('timestamp', startTs)
                  .lte('timestamp', endTs);

               if (activeScanCheckers && activeScanCheckers.length > 0) {
                  const scanNames = activeScanCheckers
                     .map(s => s.employee_name)
                     .filter(n => n && n !== 'AUTO_SYNC_CHECKER');
                  activeCheckers = [...new Set(scanNames)];
               }
            }
   
            // Priority C (Fallback): Fetch all registered employees from employees table
            if (activeCheckers.length === 0) {
               const { data: checkerEmps } = await supabase
                  .from('employees')
                  .select('name')
                  .order('name', { ascending: true });

               if (checkerEmps && checkerEmps.length > 0) {
                  const allNames = checkerEmps.map(e => e.name).filter(Boolean);
                  if (allNames.length > 0) {
                     activeCheckers = allNames;
                  }
               }
            }

            if (activeCheckers.length === 0) {
               alert("Tidak ditemukan data staff Checker. Harap tambahkan data karyawan di menu Manajemen Karyawan.");
               return;
            }

            // 1.5 ALWAYS clean up and redistribute any existing AUTO_SYNC_CHECKER items to real staff names!
            const { data: autoSyncItems } = await supabase
               .from('scanned_items')
               .select('id')
               .eq('role', 'CHECKER')
               .eq('employee_name', 'AUTO_SYNC_CHECKER');

            if (autoSyncItems && autoSyncItems.length > 0) {
               for (let i = 0; i < autoSyncItems.length; i++) {
                  const newName = activeCheckers[i % activeCheckers.length];
                  await supabase
                     .from('scanned_items')
                     .update({ employee_name: newName })
                     .eq('id', autoSyncItems[i].id);
               }
            }
   
            // 2. Fetch all PICKER barcodes today using pagination
            let pickerBarcodes = new Set<string>();
            let page = 0;
            const limit = 1000;
            let hasMore = true;
            setSyncCheckerProgress(30);
            
            while (hasMore) {
               const { data, error } = await supabase.from('scanned_items')
                  .select('barcode')
                  .eq('role', 'PICKER')
                  .gte('timestamp', startTs)
                  .lte('timestamp', endTs)
                  .range(page * limit, (page + 1) * limit - 1);
                  
               if (error) throw error;
               if (data && data.length > 0) {
                  data.forEach(item => pickerBarcodes.add(item.barcode));
                  page++;
               } else {
                  hasMore = false;
               }
            }
   
            // 3. Fetch all CHECKER barcodes today
            let checkerBarcodes = new Set<string>();
            page = 0;
            hasMore = true;
            setSyncCheckerProgress(60);
            
            while (hasMore) {
               const { data, error } = await supabase.from('scanned_items')
                  .select('barcode')
                  .eq('role', 'CHECKER')
                  .gte('timestamp', startTs)
                  .lte('timestamp', endTs)
                  .range(page * limit, (page + 1) * limit - 1);
                  
               if (error) throw error;
               if (data && data.length > 0) {
                  data.forEach(item => checkerBarcodes.add(item.barcode));
                  page++;
               } else {
                  hasMore = false;
               }
            }
   
            // 4. Find missing barcodes
            let missingBarcodes = Array.from(pickerBarcodes).filter(b => !checkerBarcodes.has(b));
            
            if (missingBarcodes.length > 0) {
               // 5. Bulk insert missing barcodes in batches (distributed evenly among activeCheckers)
               setSyncCheckerProgress(80);
               const targetTimestamp = new Date(targetDate + 'T12:00:00').getTime();
               const targetISOString = new Date(targetDate + 'T12:00:00').toISOString();
               const insertPayload = missingBarcodes.map((barcode, idx) => ({

                  id: `sync-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                  barcode: barcode,
                  role: 'CHECKER',
                  employee_name: activeCheckers[idx % activeCheckers.length],
                  timestamp: targetTimestamp,
                  status: 'COMPLETED',
                  user_email: 'auto_sync@system.local',
                  created_at: targetISOString,
                  scan_date: targetDate
               }));
      
               for (let i = 0; i < insertPayload.length; i += 1000) {
                  const chunk = insertPayload.slice(i, i + 1000);
                  const { error: insErr } = await supabase.from('scanned_items').insert(chunk);
                  if (insErr) throw insErr;
               }
            }
            
            setSyncCheckerProgress(100);
            setSuccessToast(`Berhasil memperbarui data Checker untuk ${activeCheckers.length} staff secara merata untuk tanggal ${filterDate}!`);
            
            // Refresh table view immediately
            fetchPackingData(1);
   
         } catch (err: any) {
            alert("Gagal sinkronisasi data Checker: " + err.message);
         } finally {
            setIsSyncingChecker(false);
            setSyncCheckerProgress(0);
         }
      };

