   const handleBatchCopy = async (batchId: number, text: string) => {
      const success = await copyToClipboard(text);
      if (success) {
         setBatchCopyData(prev => prev.map(b =>
            b.id === batchId ? { ...b, copied: true } : b
         ));
         setSuccessToast("Batch copied to clipboard!");
      } else {
         alert("Gagal menyalin batch ini.");
      }
   };
   const handleCopyAllBarcodes = async (includeStaff: boolean = true, forceDirect: boolean = false, copyType: 'barcode' | 'allData' = 'barcode') => {
      try {
         setIsCopyingBarcodes(true);
         // Get employee shift map for filtering
         const { data: employeesData } = await supabase.from('employees').select('name,shift');
         const shiftToNamesMap: Record<string, string[]> = {};
         employeesData?.forEach(e => {
            if (!shiftToNamesMap[e.shift]) shiftToNamesMap[e.shift] = [];
            shiftToNamesMap[e.shift].push(e.name);
         });

         // Build query but with ASCENDING order (oldest first for consistent batching)
         let query: any = supabase.from('scanned_items').select('*');
         let effectiveDate = canManageDate ? filterDate : getTodayString();

         if (effectiveDate) {
            const start = new Date(effectiveDate + 'T00:00:00');
            const end = new Date(effectiveDate + 'T23:59:59.999');
            query = query.gte('timestamp', start.getTime()).lte('timestamp', end.getTime());
         }

         if (filterPackingRole !== 'ALL') query = query.eq('role', filterPackingRole);
if (packingSearch) query = query.or(`barcode.ilike.%${packingSearch}%,employee_name.ilike.%${packingSearch}%`);
         if (filterPackingStaff !== 'ALL') {
            query = query.eq('employee_name', filterPackingStaff);
         }

         // Context Filter for Gudang Sub-menus
         const view = activeView as any;
         if (view === 'GUDANG_CANCEL') {
            query = query.eq('menu_context', 'CANCEL');
         } else if (view === 'GUDANG_PENDING') {
            query = query.eq('menu_context', 'PENDING');
         } else if (view === 'GUDANG_REPORT') {
            query = query.eq('menu_context', 'REPORT');
         } else if (view === 'GUDANG_BUNDLING') {
            query = query.eq('menu_context', 'BUNDLING');
         }

if (filterPackingShift !== 'ALL') {
            const validNames = shiftToNamesMap[filterPackingShift] || [];
            if (validNames.length > 0) query = query.in('employee_name', validNames);
            else query = query.eq('id', '00000000-0000-0000-0000-000000000000');
         }

         // IMPORTANT: Sort ASCENDING (oldest first) for consistent batch numbering
         // Data jam 07:00 pagi akan masuk Batch 1, jam 08:00 masuk setelahnya, dst.

         // REFACTOR: Use Loop Fetching to bypass 1000 row limit for "Copy All"
         let allData: any[] = [];
         let offset = 0;
         const BATCH_LIMIT = 1000;
         let fetchMore = true;

         while (fetchMore) {
            const { data: batchData, error: batchError } = await query
               .order('timestamp', { ascending: true })
               .range(offset, offset + BATCH_LIMIT - 1);

            if (batchError) throw batchError;

            if (batchData && batchData.length > 0) {
               allData = [...allData, ...batchData];
               if (batchData.length < BATCH_LIMIT) {
                  fetchMore = false;
               } else {
                  offset += BATCH_LIMIT;
               }
            } else {
               fetchMore = false;
            }

            // Safety break
            if (offset > 50000) fetchMore = false;
         }

         const data = allData;

         if (data && data.length > 0) {

            // Direct Copy Logic (No Modal)
            if (forceDirect) {
               const formattedData = data.map((item: any) => {
                  if (copyType === 'allData') {
                     return `${item.barcode}\t${item.report_keterangan || ''}\t\t${item.report_msku || ''}\t${item.report_qty || 1}`;
                  }
                  return includeStaff
                     ? `${item.barcode}\t${item.employee_name || ''}`
                     : item.barcode;
               }).join('\n');

               const success = await copyToClipboard(formattedData);
               if (success) {
                  setSuccessToast(`Berhasil menyalin ${data.length} data!`);
               } else {
                  alert("Gagal menyalin ke clipboard. Silakan coba lagi.");
               }
               return;
            }

            // Batch Copy Logic (Modal)
            const BATCH_SIZE = 500;
            const batches: BatchData[] = [];
            const totalItems = data.length;

            for (let i = 0; i < totalItems; i += BATCH_SIZE) {
               const chunk = data.slice(i, i + BATCH_SIZE);
               const formattedChunk = chunk.map((item: any) => {
                  if (copyType === 'allData') {
                     return `${item.barcode}\t${item.report_keterangan || ''}\t\t${item.report_msku || ''}\t${item.report_qty || 1}`;
                  }
                  return includeStaff
                     ? `${item.barcode}\t${item.employee_name || ''}`
                     : item.barcode;
               }).join('\n');

               // Get time range for this batch for better description
               const firstTime = chunk.length > 0 ? new Date(chunk[0].timestamp).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '';
               const lastTime = chunk.length > 0 ? new Date(chunk[chunk.length - 1].timestamp).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '';

               batches.push({
                  id: i, // distinct ID based on start index
                  start: i + 1,
                  end: Math.min(i + BATCH_SIZE, totalItems),
                  data: formattedChunk,
                  description: `Batch ${batches.length + 1} (${i + 1} - ${Math.min(i + BATCH_SIZE, totalItems)}) â€¢ ${firstTime} - ${lastTime}`,
                  copied: false,
                  count: chunk.length
               });
            }

            setBatchCopyData(batches);
            setBatchCopyMode(includeStaff ? 'STAFF' : 'BARCODE');
            setIsBatchCopyModalOpen(true);

         } else {
            alert('No data to copy');
         }
      } catch (err: any) {
         alert(`Copy failed: ${getSafeErrorMessage(err)}`);
      } finally {
         setIsCopyingBarcodes(false);
      }
   };


