   const handleCompareInvoices = () => {
      setIsComparingInvoice(true);
      try {
         // Process Kalindo Data (Support Tab/Space separated barcode and staff)
         // Format could be: "barcode staff" or just "barcode"
         const kalindoLines = kalindoDataInput.split('\n').map(l => l.trim()).filter(l => l);
         const gineeLines = gineeDataInput.split('\n').map(l => l.trim()).filter(l => l);

         const staffMap: Record<string, string> = {};
         const kalindoBarcodes: string[] = [];

         kalindoLines.forEach(line => {
            // Priority 1: Tab-separated (Excel)
            let barcode = '';
            let staff = '';

            if (line.includes('\t')) {
               const parts = line.split('\t');
               barcode = parts[0]?.trim() || '';
               staff = parts.slice(1).join(' ').trim();
            } else {
               // Fallback: Split by spaces if no Tab found
               const parts = line.split(/\s+/);
               barcode = parts[0]?.trim() || '';
               staff = parts.slice(1).join(' ').trim();
            }

            if (barcode) {
               kalindoBarcodes.push(barcode);
               if (staff) {
                  staffMap[barcode] = staff;
               }
            }
         });

         setBarcodeStaffMap(staffMap);

         // Helper to extract first column only (Barcode)
         const extractBarcodes = (lines: string[]) => {
            return lines.map(line => {
               if (line.includes('\t')) {
                  return line.split('\t')[0].trim();
               }
               return line.split(/\s+/)[0].trim();
            }).filter(b => b);
         };

         const gineeBarcodes = extractBarcodes(gineeLines);
         // Auto-sanitize Ginee input to unique list of barcodes
         const uniqueGineeBarcodes = Array.from(new Set(gineeBarcodes));
         if (uniqueGineeBarcodes.length !== gineeBarcodes.length || gineeDataInput.includes('\t')) {
            // If it had Tabs or duplicates, clean it up to show just the unique barcode list
            setGineeDataInput(uniqueGineeBarcodes.join('\n'));
         }


         const kalindoSet = new Set(kalindoBarcodes);
         const gineeSet = new Set(uniqueGineeBarcodes);

         const missingInGinee = kalindoBarcodes.filter(b => !gineeSet.has(b));
         const missingInKalindo = uniqueGineeBarcodes.filter(b => !kalindoSet.has(b));

         const getDuplicates = (arr: string[]) => {
            const counts: Record<string, number> = {};
            arr.forEach(x => counts[x] = (counts[x] || 0) + 1);
            return Object.keys(counts).filter(x => counts[x] > 1);
         };

         setComparisonResult({
            missingInGinee: Array.from(new Set(missingInGinee)),
            missingInKalindo: Array.from(new Set(missingInKalindo)),
            duplicatesKalindo: getDuplicates(kalindoBarcodes),
            duplicatesGinee: getDuplicates(uniqueGineeBarcodes),
            totalKalindo: kalindoBarcodes.length,
            totalGinee: uniqueGineeBarcodes.length
         });
      } catch (err) {
         alert("Comparison failed: " + getSafeErrorMessage(err));
      } finally {
         setIsComparingInvoice(false);
      }
   };

