   // --- MASS SEARCH LOGIC ---
   const handleMassSearch = async () => {
      if (!massSearchInputText.trim()) {
         alert("Masukkan setidaknya satu barcode.");
         return;
      }
      setIsMassSearching(true);
      setMassSearchResults([]);
      setSelectedMassSearchIds([]);
      try {
         // Parse text input to extract barcodes
         const lines = massSearchInputText.split(/[\n\t\r,;]+/);
         const barcodes = Array.from(new Set(lines.map(l => l.trim()).filter(l => l)));
         
         if (barcodes.length === 0) {
            alert("Tidak ada barcode valid yang ditemukan.");
            setIsMassSearching(false);
            return;
         }

         let allData: any[] = [];
         
         // Chunk the queries if there are too many barcodes (e.g. Supabase limit)
         const chunkSize = 200;
         for (let i = 0; i < barcodes.length; i += chunkSize) {
            const chunk = barcodes.slice(i, i + chunkSize);
            let query = supabase
               .from('scanned_items')
               .select('*')
               .in('barcode', chunk)
               .eq('status', 'COMPLETED');

            if (!massSearchRoles.includes('ALL') && massSearchRoles.length > 0) {
               const targetDbRoles: string[] = [];
               if (massSearchRoles.includes('PICKER')) targetDbRoles.push('PICKER', 'PICKER_2');
               if (massSearchRoles.includes('CHECKER')) targetDbRoles.push('CHECKER');
               if (massSearchRoles.includes('PACKING')) targetDbRoles.push('PACKING');
               if (massSearchRoles.includes('LOGISTIK')) targetDbRoles.push('LOGISTIK', 'OJOL', 'SORTIR');

               if (targetDbRoles.length > 0) {
                  query = query.in('role', targetDbRoles);
               }
            }

            const { data, error } = await query.order('timestamp', { ascending: false });

            if (error) throw error;
            if (data) {
               allData = [...allData, ...data];
            }
         }

         setMassSearchResults(allData);
         if (allData.length === 0) {
            alert("Tidak ada data ditemukan untuk barcode tersebut.");
         }
      } catch (err: any) {
         alert("Pencarian massal gagal: " + err.message);
      } finally {
         setIsMassSearching(false);
      }
   };

   const handleCopyMassSearchResults = async () => {
      if (selectedMassSearchIds.length === 0) return;
      
      const itemsToCopy = massSearchResults.filter(item => selectedMassSearchIds.includes(item.id));
      
      const uniqueItems = [];
      const seenBarcodes = new Set();
      for (const item of itemsToCopy) {
         if (!seenBarcodes.has(item.barcode)) {
             seenBarcodes.add(item.barcode);
             uniqueItems.push(item);
         }
      }

      const formattedData = uniqueItems.map(item => item.barcode).join('\n');
      
      const success = await copyToClipboard(formattedData);
      if (success) {
         setSuccessToast(`Berhasil menyalin ${uniqueItems.length} data!`);
      } else {
         alert("Gagal menyalin ke clipboard. Silakan coba lagi.");
      }
   };


   const processBatchGineeFiles = async (files: File[]) => {
      setIsImportingExcel(true);
      setImportProgress(0); // Reset progress
      setIsInvoiceImportModalOpen(false); // Close modal on start (or keep open if showing progress there, but current UI shows progress in modal... wait, no, modal closes. I should keep modal open if I want to show progress?)
      // Actually, standard behavior here: close modal, show toast or global spinner. 
      // But user requested "Add Progress Bar". If I close modal, where is the progress bar?
      // Maybe I should keep modal open?
      // Let's check where the progress bar is rendered. I haven't added one yet.
      // I will add a global progress bar overlay similar to `isExportingPacking` logic if I close the modal.
      // OR I can keep the modal open and show progress inside it.
      // "Add Progress Bar (Percentage)" in task list.
      // I'll stick to the "Global export overlay" style but for import, OR I keep modal open.
      // Let's use a Toast-like progress or keep modal open.
      // If I keep modal open, I need to prevent data input until done.
      // Re-reading: "UI Refinements... Add Progress Bar".
      // I will close modal and use the `isImportingExcel` state to render a global progress overlay similar to Export.

      // Let's UPDATE the existing `isImportingExcel` check in the JSX to show a progress bar.
      // Currently `isImportingExcel` probably just disables buttons or shows a spinner.
      // I will add a progress overlay later. First, logic.

      let totalNewBarcodes = 0;
      const allNewBarcodes: string[] = [];

      try {
         for (let i = 0; i < files.length; i++) {
            const file = files[i];

            await new Promise<void>((resolve, reject) => {
               const reader = new FileReader();
               reader.onload = (e) => {
                  try {
                     const data = new Uint8Array(e.target?.result as ArrayBuffer);
                     const workbook = XLSX.read(data, { type: 'array' });
                     const firstSheetName = workbook.SheetNames[0];
                     const worksheet = workbook.Sheets[firstSheetName];

                     // Read range
                     const range = XLSX.utils.decode_range(worksheet['!ref'] || 'A1');

                     // Indexes: C=2, D=3
                     const targetCols = [2, 3];

                     for (let r = 0; r <= range.e.r; r++) { // Start from row 0 to be safe, filter headers manually
                        targetCols.forEach(c => {
                           const cellRef = XLSX.utils.encode_cell({ r, c });
                           const cell = worksheet[cellRef];
                           if (cell && cell.v) {
                              const val = String(cell.v).trim();
                              // Filter out common headers or empty strings
                              if (val && !['barcode', 'nomor resi', 'order no', 'no. pesanan'].includes(val.toLowerCase())) {
                                 allNewBarcodes.push(val);
                              }
                           }
                        });
                     }
                     resolve();
                  } catch (err) {
                     reject(err);
                  }
               };
               reader.onerror = (err) => reject(err);
               reader.readAsArrayBuffer(file);
            });

            // Update Progress
            setImportProgress(Math.round(((i + 1) / files.length) * 100));
            // Artificial delay for visual comfort if too fast? No, speed is good.
         }

         const uniqueBarcodes = Array.from(new Set(allNewBarcodes)).filter(b => b);
         setGineeDataInput(prev => {
            const existing = prev.split('\n').map(b => b.trim()).filter(b => b);
            const combined = Array.from(new Set([...existing, ...uniqueBarcodes]));
            return combined.join('\n');
         });

         setSuccessToast(`Imported ${uniqueBarcodes.length} unique barcodes from ${files.length} file(s)!`);
      } catch (err) {
         alert("Gagal membaca file Excel: " + getSafeErrorMessage(err));
      } finally {
         setIsImportingExcel(false);
         setImportProgress(0);
      }
   };

