   // --- OJOL DATA LOGIC ---

   const buildOjolQuery = (shiftToNamesMap?: Record<string, string[]>, countOnly = false, options?: { startDate?: string, endDate?: string }) => {
      const effectiveStartDate = options?.startDate || (canManageDate ? filterDate : getTodayString());
      const activeClient = supabase;

      let query = activeClient.from('scanned_items')
         .select(countOnly ? 'id' : '*', { count: 'exact' });

      // Role Filter (OJOL)
      query = query.eq('role', 'OJOL');

      // Date Filter
      if (effectiveStartDate) {
         // Ojol original logic used 'scan_date' column.
         // Wait, 'scan_date' was used in loop. Code in view_file 2217 shows: query = query.eq('scan_date', filterDate);
         // If supporting range, I must handle scan_date logic or timestamp?
         // Ojol data usually has sync issues so we used scan_date string.
         // But for range export, Timestamp is better? Or scan_date range?
         // Let's assume scan_date is string YYYY-MM-DD.
         if (options?.startDate) {
            query = query.gte('scan_date', effectiveStartDate).lte('scan_date', options.endDate || effectiveStartDate);
         } else {
            query = query.eq('scan_date', effectiveStartDate || getTodayString());
         }
      }

      // Shift Filter -> Transform to Employee Name Filter
      if (filterOjolShift !== 'ALL' && shiftToNamesMap && !options?.startDate) {
         const namesInShift = shiftToNamesMap[filterOjolShift] || [];
         if (namesInShift.length > 0) {
            query = query.in('employee_name', namesInShift);
         } else {
            // Shift exists but has no employees? logic implies no results
            query = query.eq('employee_name', '###NO_MATCH###');
         }
      }

      // Staff Filter
      if (filterOjolStaff !== 'ALL' && !options?.startDate) {
         query = query.eq('employee_name', filterOjolStaff);
      }

      // Search Filter (Barcode or Name)
      if (ojolSearch && !options?.startDate) {
         query = query.or(`barcode.ilike.%${ojolSearch}%,employee_name.ilike.%${ojolSearch}%`);
      }

      if (!countOnly) {
         query = query.order('timestamp', { ascending: false });
      }

      return query;
   };

   const fetchOjolData = useCallback(async () => {
      if (activeView !== 'OJOL_DATA') return;
      setIsLoadingOjol(true);
      try {
         const effectiveDate = canManageDate ? filterDate : getTodayString();
         const activeClient = supabase;

         // 1. Get Shift/Map Info
         const { data: empData } = await activeClient.from('employees').select('name, shift');
         const shiftToNamesMap: Record<string, string[]> = {};
         const staffList: string[] = [];

         if (empData) {
            empData.forEach((e: any) => {
               if (e.shift) {
                  if (!shiftToNamesMap[e.shift]) shiftToNamesMap[e.shift] = [];
                  shiftToNamesMap[e.shift].push(e.name);
               }
               if (e.name) staffList.push(e.name);
            });
         }

         // APPLY SHIFT FILTER TO STAFF LIST
         let visibleStaff = staffList;
         if (filterOjolShift !== 'ALL') {
            visibleStaff = shiftToNamesMap[filterOjolShift] || [];
         }
         setOjolStaffList(Array.from(new Set(visibleStaff)).sort());

         // 2. Build Query & Pagination
         const query = buildOjolQuery(shiftToNamesMap);
         const from = (page - 1) * rowsPerPage;
         const to = from + rowsPerPage - 1;

         const { data, count, error } = await query.range(from, to);
         if (error) throw error;
         const finalData = data || [];
         setTotalRows(count || 0);

         // 3. Enrich with Shift info
         const shiftMap = new Map<string, string>();
         if (empData) {
            empData.forEach((e: any) => shiftMap.set(e.name, e.shift));
         }

         const enriched = finalData.map((item: any) => {
            let rawBarcode = (item.barcode || '').toString().trim();
            if (rawBarcode.startsWith('0026') || rawBarcode.startsWith('002')) {
               rawBarcode = rawBarcode.replace(/^00/, '');
            }
            if (/^LXAD[^-]/i.test(rawBarcode)) {
               rawBarcode = 'LXAD-' + rawBarcode.substring(4);
            }
            if (/^JNAP[^-]/i.test(rawBarcode)) {
               rawBarcode = 'JNAP-' + rawBarcode.substring(4);
            }
            if (/^JNEB[^-]/i.test(rawBarcode)) {
               rawBarcode = 'JNEB-' + rawBarcode.substring(4);
            }
            return {
               ...item,
               barcode: rawBarcode,
               shift: shiftMap.get(item.employee_name) || '-'
            };
         });
         setOjolData(enriched);

         // 4. Stats Query (Separate to ignore pagination)
         const statsQuery = buildOjolQuery(shiftToNamesMap); // Same filters
         const { data: allStatsData } = await statsQuery.select('barcode, employee_name, timestamp');

         if (allStatsData) {
            const uniqueBarcodes = new Set(allStatsData.map((i: any) => i.barcode)).size;
            const uniqueStaff = new Set(allStatsData.map((i: any) => i.employee_name)).size;
            const latest = allStatsData.length > 0 ? new Date(allStatsData[0].timestamp).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '-';
            setOjolStats({
               total: count || 0,
               distinctBarcodes: uniqueBarcodes,
               activeStaff: uniqueStaff,
               latest
            });
         }
      } catch (err: any) {
         console.error("Fetch Ojol Error", err);
      } finally {
         setIsLoadingOjol(false);
      }
   }, [activeView, filterOjolShift, filterOjolStaff, filterDate, page, rowsPerPage, ojolSearch]);

   // Trigger Fetch
   useEffect(() => {
      if (activeView === 'OJOL_DATA') {
         fetchOjolData();
      }
   }, [fetchOjolData]);

   const handleExportOjolData = async () => {
      setIsExportingOjol(true);
      setExportOjolProgress(0);
      try {
         const { data: empData } = await supabase.from('employees').select('name, shift');
         const shiftMap = new Map<string, string>();
         const shiftToNamesMap: Record<string, string[]> = {};
         if (empData) {
            empData.forEach((e: any) => {
               if (e.name && e.shift) {
                  shiftMap.set(e.name, e.shift);
                  if (!shiftToNamesMap[e.shift]) shiftToNamesMap[e.shift] = [];
                  shiftToNamesMap[e.shift].push(e.name);
               }
            });
         }

         const countQuery = buildOjolQuery(shiftToNamesMap, true);
         const { count, error: countError } = await countQuery.range(0, 1);
         if (countError) throw countError;

         const totalRecords = count || 0;
         if (totalRecords === 0) { alert("No data to export."); setIsExportingOjol(false); return; }

         const FETCH_BATCH_SIZE = 1000;
         const FILE_SPLIT_LIMIT = 5000;

         let accumulatedRows = "";
         let currentFileCount = 0;
         let fileIndex = 1;

         for (let offset = 0; offset < totalRecords; offset += FETCH_BATCH_SIZE) {
            setExportOjolProgress(Math.round((offset / totalRecords) * 100));
            const to = Math.min(offset + FETCH_BATCH_SIZE - 1, totalRecords - 1);

            const { data, error } = await buildOjolQuery(shiftToNamesMap).range(offset, to);
            if (error) throw error;
            if (!data || data.length === 0) continue;

            const enrichedBatch = data.map((item: any) => ({ ...item, shift: shiftMap.get(item.employee_name) || '-' }));
            const batchRows = enrichedBatch.map((item: any, idx: number) => {
               const dateStr = new Date(item.timestamp).toLocaleString('id-ID');
               return `${offset + idx + 1},"${dateStr}","=""${item.order_id || ''}""","=""${item.barcode}""","${item.employee_name}","${item.shift}","${item.role}","${item.status}","${item.destination || ''}","${item.description || ''}"`;
            }).join('\n');

            accumulatedRows += (accumulatedRows ? '\n' : '') + batchRows;
            currentFileCount += data.length;

            const isLastBatch = (offset + FETCH_BATCH_SIZE >= totalRecords);

            if (currentFileCount >= FILE_SPLIT_LIMIT || isLastBatch) {
               const blob = new Blob(["No,Timestamp,ID Pesanan,Barcode,Staff,Shift,Role,Status,Destination,Description\n" + accumulatedRows], { type: 'text/csv;charset=utf-8;' });
               const url = URL.createObjectURL(blob);
               const link = document.createElement("a");
               link.href = url;
               const suffix = totalRecords > FILE_SPLIT_LIMIT ? `_Part${fileIndex}` : '';
               link.setAttribute("download", `OjolData_${filterDate}${suffix}.csv`);
               document.body.appendChild(link);
               link.click();
               document.body.removeChild(link);

               accumulatedRows = "";
               currentFileCount = 0;
               fileIndex++;
               await new Promise(resolve => setTimeout(resolve, 500));
            }
         }

         setExportOjolProgress(100);
         setTimeout(() => setIsExportingOjol(false), 800);
      } catch (err: any) { alert(`Export failed: ${getSafeErrorMessage(err)}`); setIsExportingOjol(false); }
   };

