   const handleSaveQuickAdd = async () => {
      if (!quickAddValue.trim()) return;
      const table = quickAddType === 'SHIFT' ? 'app_shifts' : 'app_roles';
      const name = quickAddValue.trim();
      try {
         // Check for existence first (Case Insensitive)
         const { data: existing } = await supabase.from(table).select('name').ilike('name', name).maybeSingle();
         if (existing) {
            alert(`Gagal: Data '${existing.name}' sudah ada di database.`);
            return;
         }

         const { error } = await supabase.from(table).insert([{ name }]);
         if (error) {
            if (error.code === '42P01') {
               alert(`Table '${table}' does not exist. Please run the SQL setup script.`);
            } else if (error.code === '23505') {
               alert("This entry already exists.");
            } else {
               throw error;
            }
         } else {
            if (quickAddType === 'SHIFT') setAvailableShifts(prev => [...prev, name]);
            else setAvailableRoles(prev => [...prev, name]);
            setIsQuickAddModalOpen(false);
         }
      } catch (err: any) {
         alert(`Failed to save: ${getSafeErrorMessage(err)}`);
      }
   };

