   const processCSVImport = async (file: File) => {
      setImportProgress(10);
      const text = await file.text();
      const lines = text.split('\n').filter(l => l.trim());
      const dataRows = lines.slice(1);
      let processed = 0; const total = dataRows.length; const newEmployees: any[] = [];
      for (const row of dataRows) {
         const cols = row.match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g); if (!cols) continue;
         const cleanCols = cols.map(c => c.replace(/^"|"$/g, '').trim());
         const name = cleanCols[0]; if (!name) continue;
         const shift = cleanCols[1] || null; const target = parseInt(cleanCols[2] || '0');
         const rolesStr = cleanCols[3] || ''; const roles = rolesStr ? rolesStr.split('|').map(r => r.trim()) : [];
         newEmployees.push({ name, shift, daily_target: target, allowed_roles: roles, active: true });
         processed++; setImportProgress(10 + Math.round((processed / total) * 80));
      }
      if (newEmployees.length > 0) { const { error } = await supabase.from('employees').insert(newEmployees); if (error) { alert("Import failed: " + error.message); } else { fetchEmployees(); setIsImportModalOpen(false); } }
      setImportProgress(100);
   };

   const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files && e.target.files[0]) { processCSVImport(e.target.files[0]); } };
   const handleFileDrop = (e: React.DragEvent) => { e.preventDefault(); setIsDragOver(false); if (e.dataTransfer.files && e.dataTransfer.files[0]) { processCSVImport(e.dataTransfer.files[0]); } };

